window.QUIZ_ZK_DATA["dba13170"]=[{"id":"dba13170-pl-P4650891","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"超市复杂管理如进货、交易、库存等，主要基于（）系统实现","opts":["A. 财务软件","B. 办公软件","C. 数据库系统","D. 人力资源系统"],"ans":2,"explain":"实际上，超市的进货管理、商品交易、库存盘点、统计报表、销售预测、人员管理等复杂的管理工作都是基于数据库系统实现的。"},{"id":"dba13170-pl-P4650892","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"超市数据库中，供应商、商品等信息以（）种方式存储","opts":["A. 文本文件","B. 表格形式","C. 图像文件","D. 音频文件"],"ans":1,"explain":"超市的数据库中存储着供应商、商品、库存、销售、现金账和职工等所有运营管理信息。这些信息以表的方式存储，"},{"id":"dba13170-pl-P4650893","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"现代银行信息系统主要基于（）环境的大型数据库系统？","opts":["A. 单机环境","B. 计算机网络环境","C. 纸质文档环境","D. 本地存储环境"],"ans":1,"explain":"现代银行的信息系统是基于计算机网络环境的大型数据库系统。"},{"id":"dba13170-pl-P4650894","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"电子商务系统主要基于（）两种技术实现","opts":["A. 云计算与物联网","B. 人工智能与机器学习","C. 区块链与大数据","D. 互联网与数据库"],"ans":3,"explain":"从技术层面来看，电子商务系统是通过互联网技术加数据库技术实现的。"},{"id":"dba13170-pl-P4650895","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"信息主要描述的是（）","opts":["A. 物品的重量","B. 事物的状态与变化","C. 声音的频率","D. 颜色的深浅"],"ans":1,"explain":"信息是对事物的状态、特征、运动及变化的描述。人们通过信息可以了解事物，获得知识和概念，做出判断和行为的决策。"},{"id":"dba13170-pl-P4650896","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"现代计算机系统中，信息的存储和处理基于（）","opts":["A. 文本","B. 指令","C. 图形","D. 数据"],"ans":3,"explain":"在现代计算机系统中，信息是以数据的形式存储和处理的，数据是对事物状态和特征的表述符号，是信息的载体。"},{"id":"dba13170-pl-P4650897","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"20世纪中期，数据管理进入新阶段，主要基于（）系统","opts":["A. 纸质档案","B. 文件系统","C. 口头传播","D. 手工账本"],"ans":1,"explain":"20世纪50年代后期到20世纪60年代中期，随着计算机软硬件技术的发展，出现了磁盘、磁鼓、操作系统和文件系统等新技术，人们开始利用文件系统进行数据管理。"},{"id":"dba13170-pl-P4650898","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"早期文件系统的数据文件主要模仿（）格式","opts":["A. 电子邮件","B. 手工文档","C. 网页结构","D. 数据库表"],"ans":1,"explain":"早期文件系统的数据文件基本是模仿手工文档格式。"},{"id":"dba13170-pl-P4650899","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"文件系统中，数据管理任务主要通过（）实现","opts":["A. 硬件自动处理","B. 图形用户界面","C. 高级程序设计语言","D. 口头指令"],"ans":2,"explain":"在文件系统中，所有数据管理任务都必须用某种高级程序设计语言编写程序实现，指出要计算机做什么和怎么做。"},{"id":"dba13170-pl-P4650900","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"文件数量增加时，（）的负担会加重","opts":["A. 用户","B. 程序员","C. 硬件设备","D. 操作系统"],"ans":1,"explain":"当一个文件系统中的文件数目不断膨胀，程序人员的负担就更重了。"},{"id":"dba13170-pl-P4650901","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"DBMS中用于定义模式的是（）","opts":["A. DML","B. DDL","C. TCL","D. DCL"],"ans":1,"explain":"DBMS提供数据描述语言（DDL）定义模式。"},{"id":"dba13170-pl-P4650902","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据库的三级模式简化了（）","opts":["A. 网络安全","B. 访问控制","C. 数据抽象与操作","D. 硬件要求"],"ans":2,"explain":"数据库的三级模式是从三个层面对数据的抽象，简化了数据库实现技术和操作方式。"},{"id":"dba13170-pl-P4650903","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"外模式是（）结构的子集","opts":["A. 硬件结构","B. 网络结构","C. 全局逻辑结构（模式）","D. 进程结构"],"ans":2,"explain":"模式描述的是数据的全局逻辑结构，外模式描述的是数据的局部逻辑结构，外模式是模式的子集。"},{"id":"dba13170-pl-P4650904","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"DBS不包括以下（）部分","opts":["A. DBMS","B. DBA","C. 操作系统","D. DB"],"ans":2,"explain":"数据库系统（DBS）主要有四个组成部分，即数据库（DB）、数据库管理系统（DBMS）、数据库应用程序（Data Base Application）和数据库管理员（DBA），如图1.8所示。数"},{"id":"dba13170-pl-P4650905","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"DBMS的主要功能是（）","opts":["A. 编写代码","B. 操作数据库","C. 设计硬件","D. 绘制图表"],"ans":1,"explain":"DBMS是用于操作数据库的软件产品。"},{"id":"dba13170-pl-P4650906","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据库的主要特点是（）","opts":["A. 临时存储","B. 无组织","C. 不可共享","D. 长期存储、有组织"],"ans":3,"explain":"数据库是长期存储在计算机内，有组织的、可共享的数据集合。"},{"id":"dba13170-pl-P4650907","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"数据模型主要用于（）","opts":["A. 加密数据","B. 储存硬件信息","C. 跨平台通信","D. 交流设计信息"],"ans":3,"explain":"数据模型是数据库设计人员、程序员和最终用户之间进行交流的工具。"},{"id":"dba13170-pl-P4650908","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"描述全局逻辑结构的模型是（）","opts":["A. 物理模型","B. 逻辑模型","C. 概念模型","D. 架构模型"],"ans":2,"explain":"从用户信息需求观点描述数据库全局逻辑结构的模型称为概念模型。"},{"id":"dba13170-pl-P4650909","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"自80年代起，（）数据模型成为主流","opts":["A. 层次模型","B. 网状模型","C. 关系模型","D. 面向对象模型"],"ans":2,"explain":"自20世纪80年代开始，关系模型就成为主流的数据模型，关系数据库管理系统是应用最广泛的数据库软件，是本书重点介绍的数据模型。"},{"id":"dba13170-pl-P4650910","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"描述数据库全局逻辑结构的模型（计算机视角）是（）","opts":["A. 逻辑模型","B. 概念模型","C. 物理模型","D. 架构蓝图"],"ans":0,"explain":"从计算机实现数据库的观点描述数据库全局逻辑结构的模型称为逻辑模型。"},{"id":"dba13170-pl-P4650911","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"描述数据库物理存储结构的模型是（）","opts":["A. 逻辑模型","B. 概念模型","C. 物理模型","D. 架构模型"],"ans":2,"explain":"物理模型描述数据库在计算机物理设备上的存储结构和存取方法。"},{"id":"dba13170-pl-P4650912","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"用户定义完整性主要关注的是（）","opts":["A. 数据库间的数据一致性","B. 特定数据库的约束条件","C. 数据库的物理存储结构","D. 数据库系统的安全策略"],"ans":1,"explain":"用户定义完整性是针对某一个特定数据库的约束条件。"},{"id":"dba13170-pl-P4650913","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"表之间的关联通常依赖于（）实现","opts":["A. 索引","B. 唯一标识符","C. 公共属性（外键）","D. 排序规则"],"ans":2,"explain":"表是由行/列组成的矩阵，表与表之间的联系是通过公共属性（外键）实现的。"},{"id":"dba13170-pl-P4650914","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"并运算后结果包含（）","opts":["A. 重复元组","B. 无重复元组","C. 任意数量重复元组","D. 第一个关系的所有元组"],"ans":1,"explain":"关系代数的并运算的结果是由属于两个关系的元组构成的新关系，其结果是消除重复的元组。"},{"id":"dba13170-pl-P4650915","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"交运算结果包含（）","opts":["A. 重复元组","B. 无重复元组","C. 所有元组","D. 任意元组"],"ans":1,"explain":"关系代数的交运算的结果是由两个关系的公共元组构成的一个新关系，其结果是消除重复的元组。"},{"id":"dba13170-pl-P4650916","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"当需要调整技术员的小时工资时，应（）操作","opts":["A. 仅修改个别技术员记录","B. 批量更新所有技术员职务的小时工资","C. 无需更新，工资自动调整","D. 逐一询问每位技术员是否同意涨薪"],"ans":1,"explain":"更新异常。假设要修改技术员的小时工资，就必须修改所有职务为技术员的小时工资。"},{"id":"dba13170-pl-P4651053","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:超市的数据库中存储着供应商、_________销售、现金账和职工等所有运营管理信息。","opts":[],"ans":null,"explain":"商品、库存、"},{"id":"dba13170-pl-P4651054","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:现代银行的________是基于计算机网络环境的大型数据库系统。","opts":[],"ans":null,"explain":"信息系统"},{"id":"dba13170-pl-P4651055","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:数据库系统能够实现信息的存储、____________，这些都是考生要在本门课程中学习的内容。","opts":[],"ans":null,"explain":"管理和操作"},{"id":"dba13170-pl-P4651056","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据管理的含义","opts":[],"ans":null,"explain":"数据管理是指对数据进行分类、组织、编码、存储、检索和维护等操作。"},{"id":"dba13170-pl-P4651057","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:数据管理是数据处理过程中必要的___________。","opts":[],"ans":null,"explain":"基本环节"},{"id":"dba13170-pl-P4651058","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"若要修改文件结构中的一个字段，则必须编写程序完成哪些步骤？","opts":[],"ans":null,"explain":"1、在一个缓冲区中，存放新的文件结构。<br/>2、在另一个缓冲区中，打开旧文件。<br/>3、从旧文件中读出一个记录。<br/>4、按新的结构对旧文件的数据进行变换操作。<br/>5、把经过变换的数据写入新的文件。<br/>6、最后不仅要删除旧文件，还必须修改所有使用该文件的程序，以适应新的文件结构。<br/>总之，当文件结构和数据发生任何微小的变化时，都必须修改或重新编写文件存取程序。其原因是文件系统的数据不独立，或称文件系统的数据依赖于程序。这是文件系统的“先天不足”。"},{"id":"dba13170-pl-P4651059","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:当文件结构和数据发生任何微小的变化时，必须修改或重新编写所有涉及存取文件的程序，这种数据与程序的依赖性特点称为_______________。","opts":[],"ans":null,"explain":"数据独立性差"},{"id":"dba13170-pl-P4651060","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:模式也称为逻辑模式，它是数据库中整体数据的逻辑结构和特征的描述，是所有用户________________。","opts":[],"ans":null,"explain":"公共的数据视图"},{"id":"dba13170-pl-P4651061","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:外模式也称为_____________","opts":[],"ans":null,"explain":"子模式和用户模式"},{"id":"dba13170-pl-P4651062","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:DBMS在三级模式之间提供两层映像：_________________和模式/内模式映像。","opts":[],"ans":null,"explain":"外模式/模式映像"},{"id":"dba13170-pl-P4651063","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:数据库中只有一个模式，也只有一个__________，所以模式/内模式映像是唯一的。","opts":[],"ans":null,"explain":"内模式"},{"id":"dba13170-pl-P4651064","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据库系统的优点","opts":[],"ans":null,"explain":"1、数据库系统不仅存储数据，还存储数据的结构信息以及数据之间的联系，这是文件系统与数据库系统的根本区别。2、创建数据库时只需要简单地定义数据的逻辑结构，不必花费大量的精力定义数据的物理结构和编写程序。       3、DBMS提供加密和权限等安全性控制机制，能够确保数据库的安全。<br/>4、数据库系统支持多用户的数据存取操作，并通过封锁机制防止并发操作可能出现的问题，实现数据共享。<br/>5、DBMS提供数据备份和数据恢复的功能，能够保证数据库的可靠性。<br/>6、数据库系统提供完整性约束功能，自动检测数据的正确性和相容性。<br/>7、数据库系统提供功能强大的SQL。"},{"id":"dba13170-pl-P4651065","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:数据库复杂的内部结构是由_________直接管理的","opts":[],"ans":null,"explain":"DBMS"},{"id":"dba13170-pl-P4651066","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述DBMS的基本功能","opts":[],"ans":null,"explain":"1、数据定义：创建数据库、定义表结构、创建索引和视图等。<br/>2、数据操作：输入、查询、更新、插入、删除数据等。<br/>3、数据库运行管理：并发控制、完整性控制、安全性控制等。<br/>4、数据库维护：自动维护系统目录，备份与恢复等可靠性保障措施。"},{"id":"dba13170-pl-P4651067","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述数据库应用程序设计方法的种类","opts":[],"ans":null,"explain":"1、SQL是用户交互式操作数据库的工具。<br/>2、按照用户需求编写存储过程、函数和触发器，并将它们作为数据库对象存储在数据库中，这是实现用户复杂业务处理程序设计的最佳途径。<br/>3、当前许多DBMS都提供应用开发组件，用户可快捷设计出屏幕格式、查询窗口、报表、菜单、应用程序和交互式操作界面，这是高效开发数据库应用程序的好方法。<br/>4、将Java、Python、C、PHP等高级编程语言与数据库连接，也是常用的编写数据库应用程序的方法。"},{"id":"dba13170-pl-P4651068","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"数据库管理员全面负责数据库管理的计划、组织、测试、监控和服务工作，主要有哪些方面。","opts":[],"ans":null,"explain":"1、向终端用户提供数据和信息<br/>2、制定数据库管理的规定、标准和规范<br/>3、确保数据库的安全性，防止非法操作的发生<br/>4、数据库的备份与恢复<br/>5、培训终端用户"},{"id":"dba13170-pl-P4651069","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:最常用的概念模型表示方法是实体-联系模型，简称_________。","opts":[],"ans":null,"explain":"E-R模型"},{"id":"dba13170-pl-P4651070","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:层次模型的数据结构是___________，网络模型的数据结构是有向图","opts":[],"ans":null,"explain":"树形结构"},{"id":"dba13170-pl-P4651071","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:从用户使用数据的观点描述数据库局部的逻辑结构的模型称为___________。","opts":[],"ans":null,"explain":"外部模型"},{"id":"dba13170-pl-P4651072","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:元组的集合称为关系实例，通常关系实例又简称为_________。","opts":[],"ans":null,"explain":"关系"},{"id":"dba13170-pl-P4651073","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"在关系模型中，关系必须满足哪些性质？","opts":[],"ans":null,"explain":"1、每一列中所有数据都是同一类型的，来自同一个域。<br/>2、每一列都有唯一的列名。<br/>3、列在表中的顺序无关紧要。<br/>4、表中任意两行不能完全相同。<br/>5、行在表中的顺序也无关紧要。<br/>6、行与列的交叉点上必须是单值（不能有一组值）。"},{"id":"dba13170-pl-P4651074","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:在一个关系中可能存在多个候选键，选取其中一个_____________。","opts":[],"ans":null,"explain":"候选键作为主键"},{"id":"dba13170-pl-P4651075","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:实体完整性是指_____________，因为空值不是0，也不是空字符串，而是不确定值。","opts":[],"ans":null,"explain":"主键不能取空值"},{"id":"dba13170-pl-P4651076","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:关系模型的基本结构是表（Table），表又称为________。","opts":[],"ans":null,"explain":"关系"},{"id":"dba13170-pl-P4651077","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:投影运算是从关系中选择某些属性以构成一个新的关系，投影的结果将____________","opts":[],"ans":null,"explain":"消除重复元组"},{"id":"dba13170-pl-P4651078","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:关系代数的并运算的结果是由属于两个关系的元组构成的新关系，其结果是__________。","opts":[],"ans":null,"explain":"消除重复的元组"},{"id":"dba13170-pl-P4651079","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"填空题:自然连接运算是从两个关系的笛卡儿积中选择公共属性值相等的元组，并___________________。","opts":[],"ans":null,"explain":"消除重复属性以构成新关系"},{"id":"dba13170-pl-P4651050","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"设计题：设计一个包含数值、字符和日期三种数据类型的数据库表结构，并简述每种数据类型的用途。","opts":[],"ans":null,"explain":"在定义表的结构时，必须确定列的数据类型。绝大多数的数据库系统都至少支持以下几种数据类型。 ● 数值：可以进行算术运算的数据。 ● 字符：字符型数据也称字符串，是由任何字符或符号组成的文字串。例如，姓名、地址、专业都是字符型数据。 ● 日期：可以按照特定格式存储日期型数据，可以对日期型数据进行特殊的数学运算。 例如，一个日期减去另一个日期就可以求出两个日期之间的天数。 实际的DBMS具有更丰富的数据类型，例如，在MySQL中，有整型（int）、位类型（bit）、浮点（float、double和real）、定点数（decimal、numeric）、字符串（char、varchar和text）、日期时间（date、time、datetime和year）、二进制数据（blob、binary）、枚举（enum）、集合（set）等多种常用的数据类型。每一种数据类型又有多种格式。\n1、表名：员工信息表<br/>数值型字段：员工ID（整型，唯一标识每个员工）<br/>字符型字段：姓名（字符串，存储员工姓名）、地址（字符串，存储员工住址）<br/>日期型字段：入职日期（日期，记录员工入职的具体日期）<br/>2、用途简述：<br/>数值型字段用于存储可以进行算术运算的数据，如员工ID作为唯一标识符。<br/>字符型字段用于存储由字符或符号组成的文字串，如员工的姓名和地址信息。<br/>日期型字段用于按照特定格式存储日期数据，并允许对日期进行特殊数学运算，如计算员工入职天数。"},{"id":"dba13170-pl-P4651051","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"描述并绘制一个包含员工表和部门表的关系数据库结构，其中员工表通过部门编号作为外键与部门表实现一对多关系。请简述如何通过外键实现数据查询，如查询某员工所属部门的名称。","opts":[],"ans":null,"explain":"关系数据库结构包括两个表：员工表和部门表。员工表包含员工ID、姓名、部门编号等字段，其中部门编号是外键，指向部门表的主键。部门表包含部门编号、部门名称、部门经理等字段。<br/>查询某员工所属部门名称的方法是通过在员工表中查找该员工的部门编号，然后使用这个部门编号作为查询条件在部门表中查找对应的部门名称。具体SQL查询语句可能如下（假设要查询的员工ID为1）：<br/>1、SELECT 部门名称  <br/>2、FROM 部门表  <br/>3、WHERE 部门编号 = (  <br/>4、    SELECT 部门编号  <br/>5、    FROM 员工表  <br/>6、    WHERE 员工ID = 1  <br/>7、);<br/>通过这种方式，外键作为纽带实现了员工表和部门表之间的数据关联和查询。"},{"id":"dba13170-pl-P4651052","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"考虑一个订单系统，包括客户表和订单表，其中“客户编号”为客户表主键及订单表外键。分析以下操作是否符合参照完整性及非空约束要求： 1、插入一个新客户到客户表，客户编号为15，并尝试在订单表中新增一行订单，客户编号为16（客户表中无此编号）。 2、删除客户表中客户编号为1的客户，此时订单表中有一条订单的客户编号也是1。 3、欲将客户表中客户编号由1修改为100，但订单表中有一条订单的客户编号仍为1。 4、设定订单表中的客户编号不允许为空，且执行一个更新操作将某订单的客户编号设为NULL。","opts":[],"ans":null,"explain":"参照完整性是指外键的值必须是参照表主键的有效值，或者是空值。如果外键存在一个值，则这个值必须是参照表主键的有效值。换句话说，外键可以没有值，但不允许是一个无效值。在数据库系统中，一旦定义参照完整性约束，DBMS将会自动地维护参照完整性规则。 【例2.1】 有客户表和订单表，它们之间存在一对多联系，“客户编号”是客户表的主键和订单表的外键，表中已经输入多行数据，如图2.3所示，分析参照完整性约束效果。 ①假设在订单表中插入一个新的订单：{81，8，2023/8/28，2023/8/29}，由于客户表中不存在客户编号为8的客户，外键是一个无效值，因此该插入操作将被拒绝。 ②如果要删除客户表中客户编号为7的行，那么将导致订单表中客户编号=7成为无效值，因此该删除操作将被拒绝。 ③如果将客户表中的客户编号由7改成10，那么将导致订单表中客户编号=7成为无效值，因此该更新操作将被拒绝。 ④如果业务规则限定订单表中的客户编号不允许为空值，则在定义参照完整性后，还需要增加一个用户自定义完整性：客户编号非空（NOT NULL），确保每一个订单都必须对应一个确定的客户。\n1、不符合。因为尝试在订单表中插入的客户编号16在客户表中不存在，违反了外键约束。<br/>2、不符合。删除客户表中存在的客户编号将导致订单表中相关订单的客户编号成为无效值，违反参照完整性约束。<br/>3、不符合。修改客户表中的客户编号而不相应地更新订单表会导致订单表中的外键成为无效值，违反参照完整性约束。<br/>4、不符合。如果已设定订单表中的客户编号不允许为空，则将其更新为NULL将违反非空（NOT NULL）约束。"},{"id":"dba13170-pl-P4650917","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"物理结构设计的主要目标是（）","opts":["A. 确定最合适的逻辑结构","B. 为逻辑结构选择最佳物理实现","C. 优化应用程序的性能","D. 评估不同环境对系统的影响"],"ans":1,"explain":"物理结构设计是为一个给定的逻辑结构选取一个最适合应用环境的物理结构的过程。"},{"id":"dba13170-pl-P4650918","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"E-R模型与关系规范化在设计中的关系是（）","opts":["A. 两者相互排斥","B. 宏观与微观的结合","C. 仅用于大型系统设计","D. 仅在数据建模阶段使用"],"ans":1,"explain":"E-R模型方法主要从宏观角度解决一个企业内部所有数据需求和数据联系的概念模型设计问题，关系规范化方法则是从微观角度研究每一个关系模式是否优化的问题。这两种方法的侧重点和效果有所不同，可以在设计过程中将两种技术混合应用。"},{"id":"dba13170-pl-P4651080","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述数据库的设计方法","opts":[],"ans":null,"explain":"（1）新奥尔良方法。将数据库设计分为需求分析、概念结构设计、逻辑结构设计、物理结构设计四个阶段。在每一个设计阶段使用一些辅助设计工具，如数据流程图、业务流程图等，运用软件工程的思想，是一种规范的设计方法。<br/>（2）基于3NF的设计方法。基于关系规范化理论进行数据库设计，在第二章第五节已经详细介绍。<br/>（3）E-R模型方法。这种方法将客观事物抽象为实体，事物之间的联系抽象为实体之间的联系，称为E-R模型。用E-R模型描述现实世界复杂的事物及其联系。E-R模型是一种成熟和较为常用的数据库设计方法。<br/>（4）面向对象（OO）数据库设计方法。这种方法采用面向对象的概念构造对象模型，再将对象模型转换为数据库结构。目前，面向对象的数据库管理系统尚无成熟的产品。"},{"id":"dba13170-pl-P4651081","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述需求分析","opts":[],"ans":null,"explain":"1、需求分析阶段的任务是通过详细的调查研究，充分了解用户对信息处理和数据的需求，确定系统的功能和每个功能对数据的需求，以及用户对数据完整性约束条件和安全性等要求。                                                2、需求分析是整个数据库应用系统开发的基础，也是其后各个阶段的设计依据，能否正确和全面地了解用户实际要求，将直接影响系统开发的成败和优劣。"},{"id":"dba13170-pl-P4651082","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:逻辑结构设计的任务就是把概念模型转换成所选择的________支持的数据模型","opts":[],"ans":null,"explain":"DBMS"},{"id":"dba13170-pl-P4651083","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述概念模型的特点","opts":[],"ans":null,"explain":"1、简单明确表达用户业务环境数据需求、数据之间联系、数据约束条件。<br/>2、易于交流和理解，便于设计人员和用户之间沟通与交流。<br/>3、易于向各种数据模型转换，独立于具体的DBMS软件。"},{"id":"dba13170-pl-P4651084","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:___是指实体集中每一个实体所具有的性质","opts":[],"ans":null,"explain":"属性"},{"id":"dba13170-pl-P4651085","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述E-R模型转换为关系模型的规则","opts":[],"ans":null,"explain":"（1）实体集：每一个实体集创建一个同名且具有相同属性集的表，键作为表的主键。<br/>（2）一对一联系：将一个表的主键作为外键放在另一个表中。外键通常是放在存取操作比较频繁的表中，或者根据问题的语义决定放在哪一个表中。<br/>（3）一对多联系：将“一”方向表的主键作为外键放在“多”方向转换的表中，实现一对多联系。<br/>（4）多对多联系：将联系本身转换成一个表，该表的主键由两个父表的主键组合而成，且主键也是外键。"},{"id":"dba13170-pl-P4651086","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述仓库管理的业务的流程","opts":[],"ans":null,"explain":"1、供应商根据公司的采购合同将商品送到仓库，经过仓库管理员验收后，商品入库并填写入库单，记录商品入库的信息。<br/>2、公司销售人员承接客户的订单，并向仓库提交一份订单和订单明细，作为仓库发货的指令。<br/>3、仓库管理员根据订单和库存商品的状况，将商品发送给客户，并填写出库单。"},{"id":"dba13170-pl-P4650919","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在Windows平台上，（）方便地控制MySQL服务器的启动和停止","opts":["A. 使用MySQL命令行","B. 利用Windows服务管理器","C. 修改MySQL配置文件","D. 重启计算机"],"ans":1,"explain":"Windows平台的MySQL可以利用Windows服务管理器方便地控制MySQL服务器的启动和停止"},{"id":"dba13170-pl-P4650920","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"成功启动MySQL服务器后，下一步操作是（）","opts":["A. 修改配置文件","B. 连接到MySQL服务器","C. 重启计算机","D. 退出MySQL服务器"],"ans":1,"explain":"进入MySQL系统，启动MySQL服务器之后，还需要连接（即登录）MySQL服务器。"},{"id":"dba13170-pl-P4650921","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"Windows系统中，Path环境变量的主要作用是（）","opts":["A. 存储用户密码","B. 指定可执行文件搜索路径","C. 控制系统启动项","D. 管理系统临时文件"],"ans":1,"explain":"Windows中的环境变量Path是用来指定可执行文件的绝对路径。"},{"id":"dba13170-pl-P4650922","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"域完整性约束不包括（）","opts":["A. 属性的数据类型","B. 属性的默认值","C. 外键约束","D. 属性的唯一性"],"ans":2,"explain":"域完整性约束是对属性值有效性的约束，包括在关系模式定义中规定的属性类型、宽度、小数位，属性是否可以取NULL值、默认值（DEFAULT）、唯一值（UNIQUE），以及基于属性的域检查子句（CHECK）等。"},{"id":"dba13170-pl-P4650923","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"主键约束不允许（）值","opts":["A. 唯一值","B. 重复值","C. 空值（NULL）","D. 任意值"],"ans":2,"explain":"主键子句（PRIMARY KEY）定义主键和实体完整性约束，约束关系的主键不允许为空值（NULL）。如果主键是单个字段，则可以将PRIMARY KEY子句放在主键字段之后。如果主键是由多个字段组成的，则作为行级约束，单独占一行。"},{"id":"dba13170-pl-P4650924","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"MySQL中，用于查看表结构的命令是（）","opts":["A. SHOW DATABASES","B. DESCRIBE","C. SHOW TABLES","D. CREATE TABLE"],"ans":1,"explain":"知识点2 查看表的结构信息 （一）MySQL中两个查看表结构的命令（二）MySQL中查看表名称的命令"},{"id":"dba13170-pl-P4650925","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"MySQL中，用于修改表结构增加新字段并默认赋值为NULL的命令是（）","opts":["A. DROP TABLE","B. ALTER TABLE ... ADD COLUMN","C. UPDATE TABLE","D. MODIFY COLUMN"],"ans":1,"explain":"可以用MySQL的ALTER TABLE语句修改表的结构。下面结合实例来说明ALTER TABLE语句的使用方法。 （一）在表中增加新字段，所有元组在这个新字段上都将赋值NULL（二）删除字段（三）修改字段的数据类型"},{"id":"dba13170-pl-P4650926","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"删除被参照表前，必须先删除（）表","opts":["A. 参照表","B. 索引表","C. 外键表","D. 临时表"],"ans":0,"explain":"删除表的SQL语句格式： DROP TABLE&lt;表名&gt;: 注意：系统不允许删除已用REFERENCES子句定义的被参照表。例如，在订单表中定义外键“客户编号”，被参照表是客户表。若要删除客户表，则必须先删除订单表，否则系统拒绝删除操作。"},{"id":"dba13170-pl-P4650927","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"SQL中，使用()选项来确保索引字段的值唯一","opts":["A. DISTINCT","B. UNIQUE","C. SINGLE","D. PRIMARY KEY"],"ans":1,"explain":"创建索引的SQL语句格式： ①索引可以建立在单个字段上，也可以建立在多个字段上。 ②UNIQUE选项用于创建唯一索引，它用来保证字段取值的唯一性。如果输入重复值，则系统自动报错。"},{"id":"dba13170-pl-P4651087","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:1974年，IBM的SanJose实验室的研究人员D.Chamberlin定义了“结构化英语查询语言”，简称___________。","opts":[],"ans":null,"explain":"SEQUEL"},{"id":"dba13170-pl-P4651088","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"SQL按用途可划分为哪些组成部分","opts":[],"ans":null,"explain":"①数据描述语言（DDL）：在数据库系统中，数据库、表、视图、索引等都是对象，用于定义这些对象的SQL语句称为DDL。<br/>②数据操纵语言（DML）：用于插入、更新、删除和查询数据的SQL语句称为DML。<br/>③数据控制语言（DCL）：用于实现数据完整性、安全性、一致性等控制的SQL语句称为DCL。"},{"id":"dba13170-pl-P4651089","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:MySQL的主要特点是开源、___________________速度快、成本低。","opts":[],"ans":null,"explain":"跨平台、体积小、"},{"id":"dba13170-pl-P4651090","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:创建一个数据库，数据库的名称为__________。","opts":[],"ans":null,"explain":"COMP_DB"},{"id":"dba13170-pl-P4651091","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在MySQL中，数据库服务器上可以创建多个数据库，但每一个用户每次只能对一个数据库进行数据操作，该数据库称为_________。","opts":[],"ans":null,"explain":"当前数据库"},{"id":"dba13170-pl-P4651092","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:外键子句（FOREIGN KEY）定义外键和____________","opts":[],"ans":null,"explain":"参照完整性约束"},{"id":"dba13170-pl-P4651093","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"在MySQL中，增强了参照完整性约束功能。应对父表更新（或者删除）操作，可以选择在子表上定义哪些操作。","opts":[],"ans":null,"explain":"1、使用CASCADE进行级联更新或级联删除<br/>当父表进行DELETE或UPDATE操作时，子表也进行DELETE或UPDATE操作。<br/>2、利用SET NULL将子表上匹配记录的列设置为NULL<br/>当父表进行DELETE或UPDATE操作时，子表中的相关数据设置为NULL，即子表中对应列的值设置为NULL。<br/>3、NO ACTION和RESTRICT<br/>当父表进行DELETE或UPDATE操作时，提示错误信息，拒绝这类操作发生。<br/>在MySQL中，实现上述约束的方法是在子表的外键子句的定义中使用下列短语。"},{"id":"dba13170-pl-P4651094","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在MySQL中，删除索引的SQL语句有两种格式：ALTER TABLE&lt;表名&gt;DROP INDEX&lt; 索引名&gt;;DROP INDEX___________ON&lt;表名&gt;","opts":[],"ans":null,"explain":"&lt;索引名&gt;"},{"id":"dba13170-pl-P4650928","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"以下SQL语句中，关于创建“名单”表的错误是（）","opts":["A. 表名“名单”未使用引号","B. 性别字段的数据类型定义正确","C. 姓名字段的数据类型定义正确","D. 正确的SQL语句应该是：CREATE TABLE 名单 (姓名 CHAR(8), 性别 CHAR(2));"],"ans":2,"explain":"创建一个名单表，SQL语句如下：CREATE TABLE 名单（姓名CHLAR（8），性别CHAR（2)）"},{"id":"dba13170-pl-P4650929","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"要查看订单号为“D2”且商品编码为“P2”的商品的原始订购数量，应执行（）SQL语句","opts":["A. SELECT 订购数量 FROM 订单明细 WHERE 订单号=&#039;D2&#039; AND 商品编码=&#039;P2&#039;;","B. UPDATE 订单明细 SET 订购数量=订购数量*1.1 WHERE 订单号=&#039;D2&#039; AND 商品编码=&#039;P2&#039;;","C. SELECT * FROM 订单明细 WHERE 订单号=&#039;D2&#039;;","D. INSERT INTO 订单明细 (订单号, 商品编码, 订购数量) VALUES (&#039;D2&#039;, &#039;P2&#039;, 100);"],"ans":0,"explain":"将订单明细表中订单号为“D2”、商品编码为“P2”的商品的订购数量增加10%：①查看原来订购数量。在MySQL命令行窗口输入下列语句：SELECT *FROM订单明细WHERE订单号=&#039;D2&#039;AND商品编码=&#039;P2&#039;;"},{"id":"dba13170-pl-P4650930","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"（）SQL语句用于查看特定订单和商品的更新结果","opts":["A. SELECT * FROM 订单明细 WHERE 订单号=&#039;D2&#039;","B. SELECT * FROM 订单明细 WHERE 商品编码=&#039;P2&#039;","C. SELECT * FROM 订单明细 WHERE 订单号=&#039;D2&#039; AND 商品编码=&#039;P2&#039;","D. UPDATE 订单明细 SET * WHERE 订单号=&#039;D2&#039; AND 商品编码=&#039;P2&#039;"],"ans":2,"explain":"查看更新结果，在MySQL命令行窗口输入下列语句：SELECT*FROM订单明细WHERE订单号=&#039;D2&#039;AND商品编码=&#039;P2&#039;；"},{"id":"dba13170-pl-P4650931","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"以下（）SQL语句的语法是正确的删除语句","opts":["A. DELETE FROM 表名 WHERE 条件表达式","B. DELETE * FROM 表名 WHERE 条件表达式","C. DELETE FROM 表名 &lt;WHERE 条件表达式&gt;","D. DELETE FROM 表名 条件表达式"],"ans":0,"explain":"在SQL中，删除数据语句格式：DELETEFROM表名&gt;WHERE&lt;条件表达式&gt;:"},{"id":"dba13170-pl-P4650932","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"（）SQL语句存在语法错误","opts":["A. SELECT * FROM 职工 WHERE 职务=&#039;经理&#039;","B. SELECT * FROM 职工 WHERE 职务=&#039;经理；&#039;","C. SELECT * FROM 职工 WHERE 职务 = 经理","D. SELECT * FROM 职工 WHERE 职务 = &#039;经理&#039;"],"ans":1,"explain":"列出职工表中职务为“经理”的职工的所有信息。在MySQL命令行窗口输入下列语句：SELECT *FROM职工WHERE职务=&#039;经理；"},{"id":"dba13170-pl-P4650933","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"逻辑运算符有AND（逻辑与）、___________和NOT（逻辑非）。","opts":["A. 数值","B. 字符串","C. 逻辑值","D. 日期"],"ans":2,"explain":"（1）比较运算符 比较运算符有&lt;、&lt;=、&gt;、&gt;=、=、&lt;&gt;，用于字符串表达式、算术表达式，以及特殊类型（如日期类型）的比较。比较表达式的运算结果是逻辑值真（T）或假（F），即表达式成立为真，否则为假。"},{"id":"dba13170-pl-P4650934","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"FROM子句指定查询语句的数据来源（表名）。","opts":["A. 插入数据","B. 选择数据","C. 更新数据","D. 删除数据"],"ans":1,"explain":"（二）WHERE子句 WHERE子句的功能相当于关系代数的选择运算，指定从表中选择行的条件。条件表达式中可使用比较运算符、逻辑运算符和算术运算符。WHERE子句中使用的运算符如下。"},{"id":"dba13170-pl-P4650935","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"()SQL操作可通过子查询在所有数据库系统中实现","opts":["A. 并和交","B. 并和差","C. 只有并","D. 差和交"],"ans":3,"explain":"某些数据库系统的SQL具有专门的并、交、差操作语句，也有一些只有并操作语句，差和交操作可以通过子查询等方法实现。"},{"id":"dba13170-pl-P4650936","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"聚合函数的作用是对一组值进行()操作","opts":["A. 排序","B. 筛选","C. 计算并返回单个值","D. 连接"],"ans":2,"explain":"聚合函数是对一组值进行计算，并返回单个值的函数。"},{"id":"dba13170-pl-P4650937","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"统计客户编号为“C2”的订单总金额应使用()函数","opts":["A. COUNT","B. SUM","C. AVG","D. MAX"],"ans":1,"explain":"（二）求总和函数 聚合函数SUM用于计算列中数值的总和，函数SUM的参数必须是数值型。例4.45统计客户编号为“C2”的订单总金额。"},{"id":"dba13170-pl-P4650938","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"（）子句用于对分组结果进行筛选","opts":["A. GROUP BY","B. HAVING","C. WHERE","D. ORDER BY"],"ans":1,"explain":"分组（GROUP BY和HAVING子句） 在SQL的查询语句中，可以用GROUP BY子句实现对查询结果的分组，还可以利用HAVING子句对GROUP BY分组的结果进行筛选，保留满足条件的分组。"},{"id":"dba13170-pl-P4650939","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"（）查询涉及两个或更多表","opts":["A. 插入查询","B. 更新查询","C. 连接查询","D. 聚合查询"],"ans":2,"explain":"同时涉及两个及两个以上表的查询称为连接查询。"},{"id":"dba13170-pl-P4650940","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在SQL早期版本中，连接操作通常在（）子句中指定连接条件","opts":["A. SELECT","B. FROM","C. WHERE","D. JOIN"],"ans":2,"explain":"在SQL的早期版本中，实现连接操作的方法是在FROM子句中指定连接操作的表名，在WHERE子句中给出连接条件。"},{"id":"dba13170-pl-P4650941","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"内连接（INNER JOIN）通常也被称为（）类型的连接","opts":["A. 交叉连接","B. 等值连接","C. 左连接","D. 右连接"],"ans":1,"explain":"内连接（INNER JOIN）也称为等值连接。"},{"id":"dba13170-pl-P4650942","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"自然连接的主要特点是（）","opts":["A. 需要指定连接条件","B. 消除结果中的重复列","C. 仅适用于两个表的连接","D. 是SQL中唯一的连接类型"],"ans":1,"explain":"自然连接是以公共属性值相等为条件的连接，且消除重复列。自然连接是最常用的连接操作。"},{"id":"dba13170-pl-P4650943","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"左外连接（LEFT OUTER JOIN）的特点是（）","opts":["A. 仅包含内连接的结果","B. 包含左表所有元组，右表不匹配时为空","C. 包含右表所有元组，左表不匹配时为空","D. 总是返回两个表的全部元组"],"ans":1,"explain":"左外连接（LEFT OUTER JOIN）的结果中，除内连接结果以外，还包括左表不相匹配的元组，且其对应的右表值为空值。"},{"id":"dba13170-pl-P4650944","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于左外连接的SQL子句格式，下列（）是正确的","opts":["A. FROM 左表 LEFT OUTER JOIN 右表 ON 连接条件","B. FROM 左表 EFT OUTER JOIN 右表 (连接条件)","C. FROM 左表 OUTER JOIN 右表 ON 连接条件","D. FROM 左表 LEFT JOIN 右表 &gt; 连接条件"],"ans":0,"explain":"实现左外连接的SQL子句格式：FROM左表EFTOUTERJOIN表O(连接条件&gt;)"},{"id":"dba13170-pl-P4650945","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于右外连接的SQL子句，（）描述正确","opts":["A. RIGHT JOIN","B. LEFT OUTER JOIN","C. RIGHT OUTER ON","D. RIGHT OUTER JOIN ON"],"ans":3,"explain":"实现右外连接的SQL子句格式：FROM有表RIGHTOUTERJOIN左表ON(件&gt;）"},{"id":"dba13170-pl-P4650946","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"以下（）SQL语法错误在给出的查询语句中","opts":["A. R.工资","B. S.T资","C. R.姓名","D. FROM 职工R,职工s"],"ans":1,"explain":"列出职工中比何乃云工资高的职工姓名和工资。在MySQL命令行窗口输入下列语句：SELECT R.姓名,R.工资 FROM 职工R,职工s WHERE R.工资&gt;S.T资AND S.姓名=&#039;何乃云&#039;；"},{"id":"dba13170-pl-P4650947","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"嵌套查询中连接内外层常用（）运算符号","opts":["A. AND","B. OR","C. IN 或 NOT IN","D. BETWEEN"],"ans":2,"explain":"在嵌套查询中，常将IN或NOT IN运算符号作为外层查询与内层查询之间的连接运算符号，假设子查询结果为关系R，则内、外层查询之间的连接格式可以写成：WHERE&lt;表达式e&gt;[NOT]IN(R)"},{"id":"dba13170-pl-P4650948","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"子查询与外层查询的连接常使用（）符号","opts":["A. =","B. IN","C. JOIN","D. LIKE"],"ans":1,"explain":"在嵌套查询中，常将IN或NOT IN运算符号作为外层查询与内层查询之间的连接运算符号，假设子查询结果为关系R，则内、外层查询之间的连接格式可以写成：WHERE&lt;表达式e&gt;[NOT]IN(R)"},{"id":"dba13170-pl-P4650949","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于子查询的结果，以下（）说法正确","opts":["A. 总是单个值","B. 总是多个值","C. 必然是一个关系","D. 只能是数字类型"],"ans":2,"explain":"由于查询语句的运行结果是一个关系（元组的集合），因此子查询的结果必然也是一个关系。"},{"id":"dba13170-pl-P4650950","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于三层嵌套查询，（）选项正确描述了最外层查询的结果条件","opts":["A. 客户编号必须为&#039;C1&#039;或&#039;C2&#039;","B. 客户编号必须为&#039;D1&#039;或&#039;D2&#039;","C. 联系人名称必须为&#039;C1&#039;或&#039;C2&#039;","D. 客户名称必须为&#039;C1&#039;或&#039;C2&#039;"],"ans":0,"explain":"这是一个3层嵌套查询，属于不相关子查询。下面分析这条查询语句的执行过程。 ①执行最内层子查询的结果是（&#039;D1&#039;，&#039;D2&#039;）。 ②执行第二层子查询的结果是（&#039;C1&#039;，&#039;C2&#039;）。 ③执行最外层查询：SELECT客户名称,联系人 FROM 客户 WHERE客户编号IN(&#039;C&#039;&#039;C2&#039;);"},{"id":"dba13170-pl-P4650951","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于子查询的使用，以下（）说法正确","opts":["A. 只能在SELECT语句中使用","B. 可以在UPDATE语句的WHERE子句中使用","C. 不能用于INSERT语句","D. 在ORDER BY中不能使用"],"ans":1,"explain":"在扩展的SQL系统中，还可以用子查询替代表达式，除在ORDER BY列表中以外，在SELECT、UPDATE、INSERT和DELETE语句中，任何可以使用表达式的地方都可以使用子查询来替代。"},{"id":"dba13170-pl-P4650952","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"关于查询职工工资与平均工资差额的SQL语句，（）描述正确","opts":["A. 查询了职工号、姓名、工资及平均工资","B. 平均工资未正确保留两位小数","C. 差额计算正确无误","D. 使用了错误的聚合函数"],"ans":1,"explain":"列出职工的工资、平均工资，以及每个人的工资与平均工资之间的差额。 在MySQL命令行窗口输入下列语句：SELECT 职工号,姓名,工资,(SELECT ROUND(AVG(工资),2)FROM 职工)AS平均工资 工资-(SELECT ROUND(AVG(工资))FROM职工)AS 差额FROM 职工;"},{"id":"dba13170-pl-P4651095","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在SQL中，数据插入语句有三种格式。 （一）指定字段名和要插入的值（二）_________________________（三）利用MySQL的扩展功能，在表中一次插入多行数据","opts":[],"ans":null,"explain":"将VALUES子句换成一个查询语句"},{"id":"dba13170-pl-P4651096","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:MySQL中数据更新语句格式：UPDATE&lt;表名&gt;SET&lt;列名 1&gt;=&lt;新值 1&gt;,&lt;列名 2&gt;=&lt;新值 2&gt;,…________&lt;条件表达式&gt;","opts":[],"ans":null,"explain":"WHERE"},{"id":"dba13170-pl-P4651097","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在MySQL命令行窗口输入下列语句：DELETE FROM职__________联T号=&#039;E3&#039;:","opts":[],"ans":null,"explain":"TWHERE"},{"id":"dba13170-pl-P4651098","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在WHERE子句中，给出__________。","opts":[],"ans":null,"explain":"OR（逻辑或）"},{"id":"dba13170-pl-P4651099","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:简述字符串匹配符的用法举例","opts":[],"ans":null,"explain":"连接条件"},{"id":"dba13170-pl-P4651100","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"BETWEEN…AND…：___________________","opts":[],"ans":null,"explain":"①百分号“%”：表示任意字符串。<br/>②下画线“_”：表示任何一个字符。"},{"id":"dba13170-pl-P4651101","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"如果要检索工资不在3000元到5000元范围内的职工信息，则WHERE子句可写成：WHERE I资NOT BETWEEN 3000 AND 5000","opts":[],"ans":null,"explain":"1、&quot;Be%&quot;表示任何以“Be”开头的字符串；<br/>2、&quot;%idge%&quot;表示任何包含“idge”的字符串；<br/>3、&quot;------&quot;表示只含有六个字符的字符串；<br/>4、&quot;------%&quot;表示至少含有六个字符的字符串。"},{"id":"dba13170-pl-P4651102","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在SQL的查询语句中，可以利用__________子句对查询结果进行排序。","opts":[],"ans":null,"explain":"在某个范围之内"},{"id":"dba13170-pl-P4651103","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在查询结果中，通过入库单号和订单号区分P1商品的______与售价","opts":[],"ans":null,"explain":"ORDER BY"},{"id":"dba13170-pl-P4651104","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:聚合函数AVG用于计算列中数值的平均值，所以函数AVG的参数必须是___________。","opts":[],"ans":null,"explain":"进价"},{"id":"dba13170-pl-P4651105","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:聚合函数MAX用于求列中的最大值，________用于求列中的最小值，这两个函数的参数允许是数值型，也可以是其他数据类型（如字符型和时间型）。","opts":[],"ans":null,"explain":"数值型"},{"id":"dba13170-pl-P4651107","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述COUNT函数的格式","opts":[],"ans":null,"explain":"1、COUNT（*）：统计所有行数，包括含有空值的行。<br/>2、COUNT（字段名）：计算表中字段值非空值的行数。<br/>3、COUNT（DISTINCT（字段名））：计算表中字段值唯一且非空值的行数。"},{"id":"dba13170-pl-P4651108","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:_________用于获取字段所有的不同值，包括NULL。","opts":[],"ans":null,"explain":"DISTINCT"},{"id":"dba13170-pl-P4651109","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:GROUP BY和HAVING子句是查询语句的可选项，语法格式：SELECT&lt;字段列表&gt;FROM 表名WHERE&lt;条件表达式&gt;__________&lt;分组表达式&gt;HAVING&lt;筛选条件表达式&gt;;","opts":[],"ans":null,"explain":"GROUP BY"},{"id":"dba13170-pl-P4651110","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在MySQL命令行窗口输入下列语句：____________，COUNT(性别)AS人数 FROM职工GROUP BY性别:","opts":[],"ans":null,"explain":"SELECT性别"},{"id":"dba13170-pl-P4651111","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在SQL中，允许使用________表示某个属性的值为空（即没有值）。","opts":[],"ans":null,"explain":"NULL"},{"id":"dba13170-pl-P4651112","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在SQL中，允许在条件表达式中使用__________ISNULL来测试属性值是否为空值，或者用ISNOTNULL测试是否为非空值。","opts":[],"ans":null,"explain":"特殊的运算符号"},{"id":"dba13170-pl-P4651113","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述聚合函数对NULL的处理原则","opts":[],"ans":null,"explain":"1、SUM、AVG、MIN、MAX函数忽略参数中的空值（NULL）。若所有参数值都是空值（NULL），则函数的返回值是NULL。<br/>2、COUNT函数对参数中的空值（NULL）计数。若所有参数值都是空值（NULL），则函数的返回值是0。"},{"id":"dba13170-pl-P4651114","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述空值的处理原则","opts":[],"ans":null,"explain":"1、若算术运算（+、-、*或/）的参数中含有NULL，则该算术表达式的运算结果是NULL。<br/>2、若比较运算中有NULL作为比较对象，则比较结果为假（false）。<br/>3、SQL规定，比较运算中有NULL作为比较对象，则比较结果是“不知道”（unknown），而不用假（false）来表示。<br/>4、其他几乎所有情况都将unknown作为false。"},{"id":"dba13170-pl-P4651115","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:如果检索既是供应商又是客户的公司信息，则该查询涉及供应商和客户这两个表，连接条件：&lt;厂商名称=____________&gt;。","opts":[],"ans":null,"explain":"客户名称"},{"id":"dba13170-pl-P4651116","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:_________（RIGHT OUTER JOIN）的结果中，除内连接结果以外，还包括右表不相匹配的元组，且其对应的左表值为空值。","opts":[],"ans":null,"explain":"右外连接"},{"id":"dba13170-pl-P4651117","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述原理上分析语句的执行过程","opts":[],"ans":null,"explain":"①FROM子句中的两个关系进行笛卡儿乘积（也称乘积或交叉连接）。<br/>②从笛卡儿乘积中选择满足条件（R.工资&gt;S.工资ANDS.姓名=&#039;何乃云&#039;）的元组。<br/>③再投影。"},{"id":"dba13170-pl-P4651118","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"根据内层查询向外层查询传递数据的方式，可以将子查询分为哪些联系","opts":[],"ans":null,"explain":"一类是子查询独立运行，将查询结果传递给外层查询，外层查询再根据子查询的结果运行，称之为不相关子查询；另一类是子查询需要根据外层查询提供的数据运行，然后，将查询结果传递给外层查询，子查询的运行依赖于外层查询，称之为相关子查询。"},{"id":"dba13170-pl-P4651119","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"查询订购P1商品的客户编号。在MySQL命令行窗口输入什么语句","opts":[],"ans":null,"explain":"SELECT客户编号<br/>FROM 订单WHERE订单号IN<br/>(SELECT 订单号<br/>FROM 订单明<br/>细WHERE商品编码=&#039;PI&#039;);"},{"id":"dba13170-pl-P4651120","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"填空题:在外查询的WHERE子句中包含子查询是最常用的__________方式之一。","opts":[],"ans":null,"explain":"子查询"},{"id":"dba13170-pl-P4650953","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"创建存储过程通常属于（）数据库对象的操作","opts":["A. 视图","B. 索引","C. 触发器","D. 程序"],"ans":3,"explain":"存储过程是一个经过编译并存储在数据库中的SQL程序。在不同的DBMS中，创建存储过程的方法有所区别，但基本方法和思路大同小异。下面以MySQL创建存储过程的方法为例，介绍创建存储过程的基本方法。"},{"id":"dba13170-pl-P4650954","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"关于存储过程的创建，下列（）说法正确","opts":["A. 可在任何数据库中创建","B. 存储过程保存在客户端","C. 存储过程只能在当前数据库中创建","D. 无需编译即可使用"],"ans":2,"explain":"只能在当前数据库中创建存储过程，因为执行CREATEPROCEDURE语句后，经过编译的存储过程作为数据库的对象存储在数据库中，保存在数据库服务器端。"},{"id":"dba13170-pl-P4650955","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"存储过程的主要优点是（）","opts":["A. 简化数据库操作","B. 加速网络传输","C. 增加数据冗余","D. 替代所有SQL语句"],"ans":0,"explain":"为了用户使用更方便，DBMS针对常见的数据库操作设计了大量系统存储过程，供用户调用。用户也可以根据某些特殊业务操作，创建自己的存储过程并存储在数据库中。存储过程不仅能够简化数据库操作，而且有利于安全性控制。"},{"id":"dba13170-pl-P4650956","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"关于MySQL存储过程，以下（）是BEGIN与END之间使用的正确结束符","opts":["A. ;","B. $$","C. {","D. }"],"ans":1,"explain":"这是一个最简单的存储过程，下面解释其中的要点。 ①MySQL中默认的语句结束符为分号“;”。②EXISTS是存在量词，经常用于判断数据库、表、列、存储过程、触发器等是否存在，如果对一个存在（或者不存在）的对象进行操作，就会出现错误，所以在操作之前先判断对象是否存在很重要。③BEGIN与END $$分别表示开始和结束，相当于C语言中的大括号（{}），是一段程序的开始和结束的标志。"},{"id":"dba13170-pl-P4650957","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在SQL中，BEGIN...END语句块可以与（）控制流语句嵌套使用","opts":["A. SELECT","B. IF...ELSE","C. UPDATE","D. CREATE TABLE"],"ans":1,"explain":"说明：允许BEGIN…END语句块嵌套。通常BEGIN…END语句与IF…ELSE或WHILE等控制流语句一起使用。"},{"id":"dba13170-pl-P4650958","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL中用于循环控制的语句不包括（）","opts":["A. WHILE语句","B. REPEAT语句","C. LOOP语句","D. FOR语句"],"ans":3,"explain":"MySQL有3种用于循环控制的语句，即WHLE语句、REPEAT语句和LOOP语句。"},{"id":"dba13170-pl-P4650959","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"程序根据条件选择执行路径的结构称为（）","opts":["A. 顺序结构","B. 分支结构","C. 循环结构","D. 控制结构"],"ans":1,"explain":"流程控制结构有如下三类。 ● 顺序结构：程序从上往下依次执行。 ● 分支结构：程序从两条或多条路径中选择一条去执行。 ● 循环结构：程序在满足一定条件的基础上，重复执行一段代码。"},{"id":"dba13170-pl-P4650960","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"以下（）查询语句与给定代码片段功能相近","opts":["A. SELECT * FROM 商品 WHERE 库存数量 &lt; 最高库存","B. SELECT 商品编码 FROM 商品 WHERE 库存数量 &gt;= 最高库存 AND 商品编码 LIKE &#039;%sp_num%&#039;","C. EXISTS (SELECT * FROM 商品 WHERE 库存数量 &lt; 最低库存)","D. SELECT 品名 FROM 商品 WHERE 商品编码 = sp_num"],"ans":1,"explain":"这个代码设计看上去很复杂，但实际上只是反复使用类似下面的查询语句：EXISIS(SELECT商品编码,品名,库存数量,最高库存FROM商品WHERE库存数量&gt;=最高库存AND商品编码LKEsp_num)"},{"id":"dba13170-pl-P4650961","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL中，存储程序和（）具有相同的编程方法","opts":["A. 触发器","B. 存储函数","C. 视图","D. 索引"],"ans":1,"explain":"在MySQL中，存储程序可以分为存储过程和存储函数（简称函数），两者的编程方法相同，前面的SQL编程方法同样适用于编写存储函数。"},{"id":"dba13170-pl-P4650962","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL函数定义中，（）部分必须说明返回值数据类型","opts":["A. PARAMETERS","B. RETURNS","C. DETERMINISTIC","D. FUNCTION_BODY"],"ans":1,"explain":"说明： ①函数可以有多个参数，必须说明参数和参数的类型。 ②RETURNS必须说明返回值数据类型。 ③DETERMINISTIC声明函数是确定性函数，即参数确定后，返回值也就确定了。"},{"id":"dba13170-pl-P4650963","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"游标在SQL中的主要作用是（）","opts":["A. 管理数据库连接","B. 处理多个结果集","C. 协调集合与单记录处理","D. 执行数据备份"],"ans":2,"explain":"然而，在应用程序中常常需要对单个行或部分行进行操作，游标（CURSOR）就是用于协调SQL的集合处理方式与单记录处理方式的机制。"},{"id":"dba13170-pl-P4650964","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"以下（）步骤不是上述代码设计思路中的一部分","opts":["A. 定义SP_cur游标查询商品编码","B. 打开游标并提取商品编码","C. 调用存储过程查询商品销售数据","D. 关闭游标"],"ans":2,"explain":"代码设计思路：首先，定义一个SP_cur游标，查询商品编码，然后打开游标，依次提取商品编码并调用例5.12中创建的存储过程PROF，查询商品库存状况，直到最后一行商品为止，最后关闭游标。"},{"id":"dba13170-pl-P4650965","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"以下（）不是触发器的优点","opts":["A. 简化复杂业务实现","B. 不能直接定义完整性约束","C. 实现级联操作","D. 比较数据修改前后状态"],"ans":1,"explain":"（1）触发器能够实现相关表的级联操作。 （2）触发器具有更强大和更复杂的完整性约束定义功能。 （3）触发器可以比较数据修改前后的状态，并可根据差异而采取不同的对策。 （4）触发器能够简化复杂业务的实现方法，用简单的方法定义复杂的业务规则和完整性约束条件。 （5）由于触发器是一种特殊的存储过程，因此它具备存储过程的优点。"},{"id":"dba13170-pl-P4650966","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL触发器中，（）关键字用于引用将要变动的新数据","opts":["A. OLD","B. NEW","C. TRIGGER","D. DATA"],"ans":1,"explain":"在MySQL的触发器中，为了引用触发器触发前和触发后表中所插入、删除与更新操作时字段的变化值，提供下列两个关键字。 ①NEW将要（BEFORE）或已经（AFTER）变动的新数据，例如，INSERT型触发器中插入的新数据，UPDATE型触发器更改的新数据。 ②OLD将要（BEFORE）或已经（AFTER）变动的旧数据，例如，UPDATE型触发器中被修改的原数据，DELETE型触发器中被删除的原数据。"},{"id":"dba13170-pl-P4650967","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"数据库触发器可以实现（）","opts":["A. 数据备份","B. 简单的查询","C. 复杂的完整性约束","D. 数据索引"],"ans":2,"explain":"数据库触发器可以实现复杂的完整性约束，也可以实现用户一些特定的自动触发的业务处理。"},{"id":"dba13170-pl-P4650968","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务在数据库系统中的作用是（）","opts":["A. 提高查询速度","B. 压缩数据库文件","C. 保证数据完整性","D. 备份数据库数据"],"ans":2,"explain":"事务（Transaction）是数据库系统管理中非常重要的概念。事务是保证数据库完整性、一致性、并发控制和数据库恢复的基础理论与基本方法。"},{"id":"dba13170-pl-P4650969","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"DBMS中的执行单位是（）","opts":["A. 表","B. 索引","C. 事务","D. 视图"],"ans":2,"explain":"事务是DBMS的执行单位，它由有限的数据库操作序列组成。"},{"id":"dba13170-pl-P4650970","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）语句用于撤销事务的所有修改","opts":["A. COMMIT","B. SAVEPOINT","C. ROLLBACK","D. TRANSACTION"],"ans":2,"explain":"ROLLBACK语句：撤销该事务对数据库的所有修改，将事务回滚到事务的起点，即不执行事务的全部操作序列。"},{"id":"dba13170-pl-P4650971","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）语句用于提交事务并使修改永久生效","opts":["A. SAVEPOINT","B. COMMIT","C. ROLLBACK","D. BEGIN"],"ans":1,"explain":"COMMIT语句：提交该事务对数据库的所有修改，使其成为数据库中永久的一个部分，表示一个事务成功结束。"},{"id":"dba13170-pl-P4650972","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"并发控制的主要目的是保证()","opts":["A. 数据完整性","B. 事务隔离性","C. 系统安全性","D. 操作原子性"],"ans":1,"explain":"如果多个事务并发执行，那么应该像每个事务独立执行一样，互不干扰。并发控制就是为了保证事务之间的隔离性。"},{"id":"dba13170-pl-P4650973","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）是指数据库中的数据满足完整性约束","opts":["A. 数据安全性","B. 数据一致性","C. 数据可恢复性","D. 数据高效性"],"ans":1,"explain":"数据库的一致状态是指数据库中的数据满足完整性约束，例如，银行转账业务的完整性约束条件是转账前后账号A与B的余额之和相等。"},{"id":"dba13170-pl-P4650974","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"单CPU系统中事务（）并发执行","opts":["A. 同时并发","B. 交叉并发","C. 顺序执行","D. 同步执行"],"ans":1,"explain":"在单CPU系统中，同一时间只能有一个事务占用CPU，各个事务交叉地使用CPU，这种并发方式称为交叉并发。"},{"id":"dba13170-pl-P4650975","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"多用户对同一数据同时操作称为（）","opts":["A. 顺序操作","B. 并发操作","C. 批量操作","D. 同步操作"],"ans":1,"explain":"在多用户共享系统中，如果多个事务同时对同一数据进行操作，则称之为并发操作。"},{"id":"dba13170-pl-P4650976","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"数据库的并发操作可能导致（）问题","opts":["A. 数据丢失","B. 读脏数据","C. 数据备份失败","D. 查询速度变慢"],"ans":1,"explain":"数据库的并发操作通常会导致以下三类问题。 （一）读脏数据（Dirty read）（二）不可重复读（Unrepeatable read）（三）幻读（Phantom read）"},{"id":"dba13170-pl-P4650977","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）是指同一事务内读到不一致的数据","opts":["A. 读脏数据","B. 不可重复读","C. 幻读","D. 数据丢失"],"ans":1,"explain":"不可重复读是指在同一事务内，不同时刻读到的同一批数据是不一致的，可能是因为其他事务修改这批数据并提交了。"},{"id":"dba13170-pl-P4650978","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）是指读取未提交的数据","opts":["A. 读脏数据","B. 不可重复读","C. 幻读","D. 数据损坏"],"ans":0,"explain":"读脏数据是指一个事务读另一个更新事务尚未提交的数据，也称为读-写冲突。"},{"id":"dba13170-pl-P4650979","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"并发操作导致问题的核心原因是（）冲突","opts":["A. 读-读","B. 写-写或读-写","C. 读-写或写-读","D. 数据完整性"],"ans":1,"explain":"综上所述，并发操作导致种种问题的原因是对同一数据对象的写-写冲突或读-写冲突，问题出在“写”上。为了解决这些问题，数据库系统可实施下列多种措施。 ● 可串行化调度：使事务可串行化地执行，避免冲突。 ● 设置隔离级别：避免事务之间的相互干扰。 ● 实施加锁机制：封锁其他事务对写操作对象的访问。"},{"id":"dba13170-pl-P4650980","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"数据库系统（）安排事务执行顺序","opts":["A. 数据排序","B. 同步处理","C. 并发控制","D. 调度"],"ans":3,"explain":"为了保证这些事务相互之间不受影响，数据库系统安排这些操作执行顺序的过程称为调度。"},{"id":"dba13170-pl-P4650981","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）是指事务操作顺序不交叉","opts":["A. 并发调度","B. 串行调度","C. 交叉调度","D. 同步调度"],"ans":1,"explain":"如果各事务的操作顺序不交叉，则称为串行调度。"},{"id":"dba13170-pl-P4650982","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）调度与串行调度等价","opts":["A. 并发调度","B. 任意调度","C. 交叉调度","D. 可串行化调度"],"ans":3,"explain":"对于一个事务集，如果一个调度与一个串行调度等价，则称此调度是可串行化的。"},{"id":"dba13170-pl-P4650983","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL默认的全局、会话及事务隔离级别是（）","opts":["A. 读未提交","B. 可重复读","C. 串行化","D. 读已提交"],"ans":1,"explain":"查看隔离级别 --查看全局隔离级别，显示系统变量@@global.transaction_isolationSELECT @ @ global. transaction__isolation ; --查看当前会话中的隔离级别，显示系统变量@@session,transaction_isolationSElFCT @ @ session, transaction_isolation , --查看当前用户下一个事务的隔离级别，显示系统变量@@transac:lian_isolalionSELECT @ @ transaction isolation ; --注:global(全局)、session(当前会话)、ransaction(事务)、isolation(隔离)、level(级别)"},{"id":"dba13170-pl-P4650984","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）设置MySQL事务的隔离级别","opts":["A. ALTER TABLE","B. SET TRANSACTION ISOLATION LEVEL","C. CREATE INDEX","D. UPDATE TRANSACTION"],"ans":1,"explain":"在MySQL中，事务的隔离级别可以用SET语句设置，相关SQL语句格式：SET[SESSIONICLOBAL]TRANSACTION ISOLATION LEVEL 参数值:"},{"id":"dba13170-pl-P4650985","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）是事务中最低的隔离级别","opts":["A. READ COMMITTED","B. SERIALIZABLE","C. REPEATABLE READ","D. READ UNCOMMITTED"],"ans":3,"explain":"READ UNCOMMITTED是事务中最低的隔离级别。"},{"id":"dba13170-pl-P4650986","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（）隔离级别是多数数据库系统的默认（非MySQL）","opts":["A. READ UNCOMMITTED","B. READ COMMITTED","C. REPEATABLE READ","D. SERIALIZABLE"],"ans":1,"explain":"READ COMMITTED是大多数数据库系统的默认隔离级别（但不包括MySQL）。"},{"id":"dba13170-pl-P4650987","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"数据库作为共享资源，需确保并发访问时数据的（）性","opts":["A. 安全性","B. 一致性","C. 完整性","D. 可用性"],"ans":1,"explain":"数据库是一种共享资源，在最大程度提供并发访问性能的同时，仍需要确保每个用户能以一致的方式读取和修改数据。"},{"id":"dba13170-pl-P4650988","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务T获Q上S锁可读不可写，此锁允许其他事务同时获S锁，称为（）锁","opts":["A. 排他锁","B. 独占锁","C. 共享锁","D. 互斥锁"],"ans":2,"explain":"如果事务T获得数据项Q上的S锁，则T可读但不能写Q，而其他事务可以同时再获得Q上的S锁。这类锁具有共享性，故称为共享锁。"},{"id":"dba13170-pl-P4650989","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务T获Q上X锁可读可写，阻止其他事务获Q锁，称为（）锁","opts":["A. 共享锁","B. 读写锁","C. 排他锁","D. 互斥读写锁"],"ans":2,"explain":"如果事务T获得数据项Q上的X锁，则T既可读又可写Q，而其他事务不能再获得Q上的任何锁。这类锁具有排他性，故称为排他锁。"},{"id":"dba13170-pl-P4650990","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"（S，X）锁特点可用（）矩阵表示，体现锁相容性","opts":["A. 权限矩阵","B. 相容矩阵","C. 锁定矩阵","D. 访问矩阵"],"ans":1,"explain":"加锁协议可以用一个矩阵表示，称为相容矩阵。图6.16是（S，X）锁的相容矩阵，其描述S锁和X锁的特点。"},{"id":"dba13170-pl-P4650991","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"两阶段封锁协议中，何阶段事务可获锁不可释锁（）","opts":["A. 锁缩减阶段","B. 锁增长阶段","C. 初始阶段","D. 结束阶段"],"ans":1,"explain":"保证调度可串行化的一个协议是两阶段封锁协议（Two-phase Locking Protocol）。该协议要求一个事务分下列两个阶段提出加锁和解锁申请。 ● 锁增长阶段（Growing Phase）：事务可以获得锁，但不能释放锁。 ● 锁缩减阶段（Shrinking Phase）：事务可以释放锁，但不能获得新锁。"},{"id":"dba13170-pl-P4650992","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务T写Q前若持S锁，系统会先发出（）指令","opts":["A. lock-S(Q)","B. lock-X(Q)","C. upgrade(Q)","D. release(Q)"],"ans":2,"explain":"通常DBMS根据事务的读写请求，自动地产生加锁和解锁指令。 ● 当事务T，进行read（Q）操作时，系统将自动产生一个lock-S（Q）指令，然后执行read（Q）指令。 ● 当事务T，进行write（Q）操作时，系统先检查T;是否已经在Q上持有共享锁。若有，则系统发出锁升级指令upgrade（Q），然后执行write（Q）指令，否则系统先发出lock-X（Q）指令，再执行write（Q）指令。 ● 当一个事务提交或回滚后，该事务持有的所有锁都自动被释放。"},{"id":"dba13170-pl-P4650993","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"封锁对象的大小被称为（）","opts":["A. 封锁范围","B. 封锁级别","C. 封锁粒度","D. 封锁程度"],"ans":2,"explain":"封锁对象的大小称为封锁的粒度（Granularity）。"},{"id":"dba13170-pl-P4650994","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"微机DBMS中，并发度低时常用（）作为封锁单位","opts":["A. 行","B. 字段","C. 表","D. 数据库"],"ans":2,"explain":"在微机DBMS中，并发度不高，一般以表作为封锁单位，故这种封锁称为单粒度封锁。"},{"id":"dba13170-pl-P4650995","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务申请锁未获准时会形成（）关系","opts":["A. 竞争关系","B. 冲突关系","C. 等待关系","D. 依赖关系"],"ans":2,"explain":"若一个事务申请锁未被获准，则须等待其他事务释放锁。这就形成了事务之间的等待关系。"},{"id":"dba13170-pl-P4650996","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务间循环等待若不干预会导致（）现象","opts":["A. 锁超时","B. 死锁","C. 锁升级","D. 锁降级"],"ans":1,"explain":"当事务中出现循环等待时，如果不加以干预，则会一直等待下去，称为死锁（Dead Lock）。"},{"id":"dba13170-pl-P4650997","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"解决死锁有（）两种方法","opts":["A. 预防与检测","B. 避免与升级","C. 释放与重试","D. 忽略与解除"],"ans":0,"explain":"目前，有两种解决死锁的方法：一是采取某些措施，预防死锁发生；二是允许死锁发生，然后解除它。"},{"id":"dba13170-pl-P4650998","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL中S锁和X锁的粒度可以是（）","opts":["A. 只能是表","B. 只能是行","C. 行或表","D. 数据库"],"ans":2,"explain":"MySQL的共享（S）锁和排他（X）锁的基本概念与前面的阐述相同，锁的粒度是行或者表。"},{"id":"dba13170-pl-P4650999","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"事务A获某行排他锁后，事务B能否获该行锁（）","opts":["A. 能获共享锁","B. 能获排他锁","C. 不能，需等待","D. 可立即获任意锁"],"ans":2,"explain":"排他锁：如果事务A获取表中一行上的排他锁，那么事务B不能立即获取这一行上的共享锁，也不能获取这一行上的排他锁，必须等到事务A释放排他锁之后。"},{"id":"dba13170-pl-P4651000","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"MySQL为提升加锁效率，在S/X锁外增加了（）表级锁","opts":["A. 行级锁","B. 意向锁","C. 页级锁","D. 元数据锁"],"ans":1,"explain":"为了提高加锁效率和并发度，MySQL在S锁和X锁的基础上增加了意向锁，意向锁是表级锁，锁的粒度是整个表。"},{"id":"dba13170-pl-P4651121","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:_________是存储在数据库服务器上的SQL程序。","opts":[],"ans":null,"explain":"存储过程"},{"id":"dba13170-pl-P4651122","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述存储过程的主要优点","opts":[],"ans":null,"explain":"（1）在创建存储过程以后，可以多次调用它而不必重写程序。修改存储过程不影响调用的程序，提高了程序的可移植性。<br/>（2）存储过程不仅可用SQL语句，还可以使用一些控制程序流程的语句，如BEGIN…END、IF… THEN…ELSE、WHILE…END_WHILE等语句，定义局部变量和给变量赋值，编写复杂的业务处理程序。<br/>（3）存储过程以编译后的形式存储在数据库中，在调用时不必再进行语法分析以及查询优化处理，所以存储过程能够提高系统的执行速度。<br/>（4）存储过程能够减少网络流量。"},{"id":"dba13170-pl-P4651123","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"依据参数传递的方式，参数分为哪些类别","opts":[],"ans":null,"explain":"1、IN：输入参数（默认为IN参数），该参数的值由调用程序指定。<br/>2、OUT：输出参数，可将存储过程计算结果返回调用程序。<br/>3、INOUT：具有输入和输出两类参数的特点，参数的值由调用程序指定，又能将计算结果返回调用程序。"},{"id":"dba13170-pl-P4651124","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:通过参数传递，实现用户与存储过程之间的___________。","opts":[],"ans":null,"explain":"数据交互"},{"id":"dba13170-pl-P4651125","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述MySQL中的注释方法","opts":[],"ans":null,"explain":"1、单行注释符#：在该注释符后直接加注释内容。2、单行注释符--：在该注释符后需要加一个空格，注释才能生效。3、多行注释符/**/：从“/*”开始到“*/”结束，可以跨越多行注释内容。"},{"id":"dba13170-pl-P4651126","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:在MySQL中，有四种变量类型，即局部变量、用户变量、__________________","opts":[],"ans":null,"explain":"会话变量和全局变量"},{"id":"dba13170-pl-P4651127","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述流程控制的结构","opts":[],"ans":null,"explain":"1、顺序结构：程序从上往下依次执行。<br/>2、分支结构：程序从两条或多条路径中选择一条去执行。<br/>3、循环结构：程序在满足一定条件的基础上，重复执行一段代码。"},{"id":"dba13170-pl-P4651128","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:利用游标机制，可以将集合操作转换成__________。","opts":[],"ans":null,"explain":"单记录的处理方式"},{"id":"dba13170-pl-P4651129","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:__________（Trigger）是由事件触发的某个操作。","opts":[],"ans":null,"explain":"触发器"},{"id":"dba13170-pl-P4651130","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述触发器的特点","opts":[],"ans":null,"explain":"（1）触发器是数据库的一个对象，必须创建在一个特定的表上，并存储在数据库中。<br/>（2）如果对一个表上的某种操作（如插入、更新或删除）定义了触发器，则该操作发生时触发器将自动触发。<br/>（3）与存储过程不同，触发器不能被直接调用，也不能传递或接收参数。<br/>（4）触发器和激活它的SQL语句构成一个事务，可以在触发器中包含ROLLBACK TRANSACTION语句，根据触发器运行的状态回滚事务，撤销所有操作。<br/>（5）触发器是实现数据安全性控制的一种手段，就像保险柜的报警器一样，能够实时监控表中字段的更改，做出相应处理，例如，自动阻断某种违规操作并实时报警等。"},{"id":"dba13170-pl-P4651131","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述触发器的优点","opts":[],"ans":null,"explain":"（1）触发器能够实现相关表的级联操作。<br/>（2）触发器具有更强大和更复杂的完整性约束定义功能。<br/>（3）触发器可以比较数据修改前后的状态，并可根据差异而采取不同的对策。<br/>（4）触发器能够简化复杂业务的实现方法，用简单的方法定义复杂的业务规则和完整性约束条件。<br/>（5）由于触发器是一种特殊的存储过程，因此它具备存储过程的优点。"},{"id":"dba13170-pl-P4651132","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:_______将要（BEFORE）或已经（AFTER）变动的新数据，例如，INSERT型触发器中插入的新数据，UPDATE型触发器更改的新数据。","opts":[],"ans":null,"explain":"NEW"},{"id":"dba13170-pl-P4651133","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:________将要（BEFORE）或已经（AFTER）变动的旧数据，例如，UPDATE型触发器中被修改的原数据，DELETE型触发器中被删除的原数据。","opts":[],"ans":null,"explain":"OLD"},{"id":"dba13170-pl-P4651134","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:事务在执行时，应遵守__________________（Nothing or All）的原则，即不允许部分地完成事务。","opts":[],"ans":null,"explain":"“要么不做，要么全做”"},{"id":"dba13170-pl-P4651135","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:____________的作用是使数据库从一个一致状态转变到另一个一致状态。","opts":[],"ans":null,"explain":"事务对数据库"},{"id":"dba13170-pl-P4651136","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述ANSI/ISO SQL事务的处理模型","opts":[],"ans":null,"explain":"①执行COMMIT语句，该事务成功结束，使数据库的更新操作永久地反映到数据库中。在COMMIT语句之后，一个新的事务将立即开始。<br/>②执行ROLLBACK语句，该事务异常结束，放弃该事务对数据库的所有更新操作。在ROLLBACK语句之后，一个新事务将立即开始。<br/>③对于SQL程序，程序正常结束表示该事务也结束了，没有新的事务开始。<br/>④对于SQL程序，程序异常终止表示该事务也异常结束，没有新的事务开始。在ANSI/ISO规定的SQL事务处理模型中，用户或程序始终处于事务处理状态。"},{"id":"dba13170-pl-P4651137","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:_______________，该事务成功结束，使数据库的更新操作永久地反映到数据库中。在COMMIT语句之后，一个新的事务将立即开始。","opts":[],"ans":null,"explain":"执行COMMIT语句"},{"id":"dba13170-pl-P4651138","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述SQL Server和Sybase的事务处理模型","opts":[],"ans":null,"explain":"①BEGIN TRANSACTION：表示一个事务的开始，与ANSI/ISOSQL事务处理模型不同。<br/>②COMMIT TRANSACTION：表示一个事务成功结束，但不能自动开始一个新事务。<br/>③SAVE TRANSACTION：在事务中间建立一个保存点（Savepoint）。保存点提供了一种回滚部分事务机制。在事务执行过程中，创建一个保存点，然后，再执行“ROLLBACK TRANSACTION&lt;保存点名&gt;”语句时，将回滚到保存点，而不是回滚到事务的开始。<br/>④ROLLBACK TRANSACTION：如果设有保存点，则可以放弃保存点之后所有数据库的更新操作，回滚到保存点的状态；否则，将回滚到事务的初始状态，放弃该事务的所有更新操作。"},{"id":"dba13170-pl-P4651139","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述MySQL有哪些事务处理的SQL语句","opts":[],"ans":null,"explain":"①START TRANSACTION：在默认情况下，用户执行的每一条SQL语句都被当成单独的事务而自动提交。如果要将一组SQL语句作为一个事务，则需要先执行START TRANSACTION语句以开启一个事务。<br/>②COMMIT：在开启一个事务之后，只有执行COMMTT语句提交事务，事务的操作才能生效。<br/>③ROLLBACK：如果不想提交当前事务，则可以执行ROLLBACK语句取消事务，即事务回滚。<br/>④SAVEPOINT：当事务回滚后，事务内的所有操作都将撤销。如果只希望撤销一部分，则可以先用“SAVEPOINT&lt;保存点名&gt;”语句在事务中设置保存点，再执行“ROLLBACK TO SAVEPOINT&lt;保存点名&gt;”语句，将事务回滚到指定的保存点。"},{"id":"dba13170-pl-P4651140","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:在MySQL中，事务的隔离级别可以用SET语句设置，相关SQL语句格式：SET____________________TRANSACTION ISOLATION LEVEL 参数值:","opts":[],"ans":null,"explain":"[SESSIONICLOBAL]"},{"id":"dba13170-pl-P4651141","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:_______________--是事务中最低的隔离级别。","opts":[],"ans":null,"explain":"READ UNCOMMITTED"},{"id":"dba13170-pl-P4651142","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:___________是大多数数据库系统的默认隔离级别（但不包括MySQL）。","opts":[],"ans":null,"explain":"READ COMMITTED"},{"id":"dba13170-pl-P4651143","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:___________________是最高的隔离级别，它通过强制事务排序，在每个读的数据行上加共享锁，使之不可能相互冲突，从而解决了读脏数据、不可重复读和幻读问题。","opts":[],"ans":null,"explain":"SERIALIZABLE"},{"id":"dba13170-pl-P4651144","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述严格两阶段封锁协议","opts":[],"ans":null,"explain":"1、封锁是两阶段的。<br/>2、事务持有的所有排他锁在事务提交后方可释放。"},{"id":"dba13170-pl-P4651145","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述锁的转换必须遵守哪些规则。","opts":[],"ans":null,"explain":"锁提升只能发生在增长阶段。<br/>锁降级只能发生在缩减阶段。"},{"id":"dba13170-pl-P4651146","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:___________的大小称为封锁的粒度（Granularity）。","opts":[],"ans":null,"explain":"封锁对象"},{"id":"dba13170-pl-P4651147","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:对这些不同级别数据对象锁定的方法，称为___________。","opts":[],"ans":null,"explain":"多粒度封锁"},{"id":"dba13170-pl-P4651148","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:在微机DBMS中，并发度不高，一般以表作为封锁单位，故这种封锁称为___________。","opts":[],"ans":null,"explain":"单粒度封锁"},{"id":"dba13170-pl-P4651149","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:这就形成了事务之间的等待关系。当事务中出现循环等待时，如果不加以干预，则会一直等待下去，称为______________。","opts":[],"ans":null,"explain":"死锁（Dead Lock）"},{"id":"dba13170-pl-P4651150","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:目前，有两种解决死锁的方法：一是采取某些措施，__________________；二是允许死锁发生，然后解除它。","opts":[],"ans":null,"explain":"预防死锁发生"},{"id":"dba13170-pl-P4651151","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:这种方法有两个缺点：一是在事务的开始，很难预知有哪些数据需要封锁；二是_______________，将降低数据的使用效率。","opts":[],"ans":null,"explain":"过早地封锁数据"},{"id":"dba13170-pl-P4651152","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:MySQL的共享（S）锁和_______________的基本概念与前面的阐述相同，锁的粒度是行或者表。","opts":[],"ans":null,"explain":"排他（X）锁"},{"id":"dba13170-pl-P4651153","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:___________：如果事务A获取一行上的共享锁，那么事务B可以立即获取这一行上的共享锁，但不能获取这个行上的排他锁，必须等到事务A释放共享锁之后。","opts":[],"ans":null,"explain":"共享锁"},{"id":"dba13170-pl-P4651154","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:______________：用户手动执行SQL语句以对表或某些行加锁。","opts":[],"ans":null,"explain":"显式锁定"},{"id":"dba13170-pl-P4651155","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:行级共享锁语句格式：SELECT&lt;列名表&gt;FROM&lt;表名&gt;WHERE&lt;条件表达式&gt;___________________","opts":[],"ans":null,"explain":"LOCKINSHAREMODE;"},{"id":"dba13170-pl-P4651156","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:表级共享锁语句格式：__________&lt;表名&gt;READ:","opts":[],"ans":null,"explain":"LOCK TABLES"},{"id":"dba13170-pl-P4651157","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"填空题:表级排他锁语句格式：LOCK TABLES&lt;表名&gt;__________","opts":[],"ans":null,"explain":"WRITE;"},{"id":"dba13170-pl-P4651158","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述意向锁加锁的规则","opts":[],"ans":null,"explain":"1、意向共享锁：事务要获取表中某些行的S锁，必须先获得表的IS锁。执行下列SQL语句，数据库系统自动在表上加IS锁。2、意向排他锁：事务要获取表中某些行的X锁，必须先获得表的IX锁。执行下列SQL语句，数据库系统自动在表上加IX锁。"},{"id":"dba13170-pl-P4651001","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"事务B能否获客户表共享锁，需确认无其他事务持有（）锁","opts":["A. 仅表级共享锁","B. 表级或行级排他锁","C. 仅行级共享锁","D. 表级和行级共享锁"],"ans":1,"explain":"因为共享锁与排他锁互斥，所以事务B能否拥有客户表级的共享锁，需要判断如下两个条件： ● 当前没有其他事务在客户表上持有排他锁（表级锁）。 ● 当前没有其他事务在客户表中任意一行上持有排他锁（行级）。"},{"id":"dba13170-pl-P4651002","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）故障会导致内存数据丢失，而外存数据未受影响","opts":["A. 硬件永久损坏","B. 系统故障","C. 磁盘故障","D. 人为误删数据"],"ans":1,"explain":"系统在运行过程中由于种种原因，如硬件故障、操作系统或DBMS代码错误、突然断电、误操作等，造成系统停止运行，导致内存中的数据丢失，但外存储器设备上的数据未受影响，这种故障称为系统故障。"},{"id":"dba13170-pl-P4651003","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）故障致内存数据丢失，外存数据无损","opts":["A. 网络故障","B. 系统故障","C. 磁盘损坏","D. 人为错误"],"ans":1,"explain":"系统在运行过程中由于种种原因，如硬件故障、操作系统或DBMS代码错误、突然断电、误操作等，造成系统停止运行，导致内存中的数据丢失，但外存储器设备上的数据未受影响，这种故障称为系统故障。"},{"id":"dba13170-pl-P4651004","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）故障会导致外存数据丢失","opts":["A. 系统崩溃","B. 介质故障","C. 网络中断","D. 内存泄漏"],"ans":1,"explain":"系统在运行过程中，由于某种硬件故障，如磁盘损坏、磁头碰撞、操作系统潜在错误、瞬间强磁场干扰，造成外存储器上的数据部分或全部丢失，这种故障称为介质故障。"},{"id":"dba13170-pl-P4651005","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"计算机病毒是（）","opts":["A. 硬件故障","B. 自然现象","C. 人为编写的特殊程序","D. 系统更新错误"],"ans":2,"explain":"计算机病毒是一种人为破坏计算机正常工作的特殊程序。"},{"id":"dba13170-pl-P4651006","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）故障会导致数据库可能包含未完成事务的修改","opts":["A. 介质故障","B. 事务及系统故障","C. 计算机病毒（破坏外存）","D. 系统正常关闭"],"ans":1,"explain":"：一类是数据库本身被破坏，如发生介质故障，或遭受计算机病毒破坏；另一类是数据库本身没有被破坏，但由于有些事务在运行中非正常中止，使数据库中可能包含未完成事务对数据库的修改，破坏了数据库的正确性，使数据库处于不一致状态，如事务故障、系统故障和某些只破坏内存中数据的病毒发作导致的故障。"},{"id":"dba13170-pl-P4651007","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）是将数据库保存到磁带或另一磁盘上的过程","opts":["A. 迁移","B. 备份","C. 同步","D. 压缩"],"ans":1,"explain":"备份（Backup）是指将数据库转储到磁带或另一个磁盘上保存的过程。"},{"id":"dba13170-pl-P4651008","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）是对数据库物理文件的备份","opts":["A. 逻辑备份","B. 物理备份","C. 差异备份","D. 全量备份"],"ans":1,"explain":"物理备份是指对操作系统下数据库物理文件（如数据文件、日志文件等）的备份。"},{"id":"dba13170-pl-P4651009","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）是对数据库逻辑组件进行的备份","opts":["A. 差异备份","B. 物理备份","C. 逻辑备份","D. 系统备份"],"ans":2,"explain":"逻辑备份是指对数据库逻辑组件（如表等数据库对象）的备份。"},{"id":"dba13170-pl-P4651010","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）备份方式包含整个数据库的所有对象","opts":["A. 差异备份","B. 增量备份","C. 完全备份","D. 系统备份"],"ans":2,"explain":"完全备份：备份整个数据库，包含用户表、系统表、索引、视图和存储过程等所有数据库对象。"},{"id":"dba13170-pl-P4651011","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"增量备份备份的是（）内容","opts":["A. 整个数据库","B. 新增的数据","C. 修改后的内容","D. 系统文件"],"ans":2,"explain":"增量备份：只备份上次完全备份或者增量备份之后被修改的内容。"},{"id":"dba13170-pl-P4651012","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）备份是在数据库关闭时进行的","opts":["A. 联机备份","B. 全量备份","C. 差异备份","D. 脱机备份"],"ans":3,"explain":"物理备份又可以分为脱机备份（冷备份）和联机备份（热备份）。 ①脱机备份：在关闭数据库时进行的备份操作，能够较好地保证数据库的完整性。 ②联机备份：在数据库运行中进行的备份操作，这种备份方法依赖于数据库的日志文件。"},{"id":"dba13170-pl-P4651013","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）文件是MySQL数据库的重要组成部分","opts":["A. 索引文件","B. 备份文件","C. 日志文件","D. 配置文件"],"ans":2,"explain":"日志文件是MySQL数据库的重要组成部分和特色。"},{"id":"dba13170-pl-P4651014","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"MySQL（）间接实现增量备份","opts":["A. 使用索引文件","B. 开启binlog","C. 手动复制文件","D. 配置备份策略"],"ans":1,"explain":"MySQL没有提供直接的增量备份方法，但是可以通过开启二进制日志（binlog）间接实现增量备份。"},{"id":"dba13170-pl-P4651015","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）判断MySQL的二进制日志是否开启","opts":["A. 查看log_bin值","B. 检查索引文件","C. 查阅配置文件","D. 验证备份文件"],"ans":0,"explain":"log_bin的值为ON，说明二进制日志已经开启。如果logbin为OFF，则表示未开启，需要将它设置为开启状态，方可进行增量备份。"},{"id":"dba13170-pl-P4651016","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）查看MySQL的二进制日志","opts":["A. 输入show logs","B. 输入show binary logs","C. 查阅配置文件","D. 使用备份工具"],"ans":1,"explain":"在MySQL命令行窗口输入下列显示二进制日志命令：show binary logs ;"},{"id":"dba13170-pl-P4651017","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）过程能将数据库恢复到正确状态","opts":["A. 数据库备份","B. 数据库恢复","C. 数据库迁移","D. 数据库优化"],"ans":1,"explain":"将数据库从某种故障状态恢复到正确状态的处理过程称为数据库恢复。"},{"id":"dba13170-pl-P4651018","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"mysqldump命令备份数据生成（）文件","opts":["A. 索引文件","B. 文本文件","C. 日志文件","D. 二进制文件"],"ans":1,"explain":"使用mysql dump命令将数据库中的数据备份成一个文本文件。"},{"id":"dba13170-pl-P4651019","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"mysqldump生成的文本文件包含（）语句","opts":["A. SELECT和UPDATE","B. DELETE和CREATE","C. CREATETABLE和INSERT","D. GRANT和REVOKE"],"ans":2,"explain":"该文本文件包括CREATETABLE和INSERT语句。"},{"id":"dba13170-pl-P4651020","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）恢复方法以后备副本和事务日志为基础","opts":["A. 简单恢复模型","B. 完全恢复模型","C. 大容量日志恢复模型","D. 点恢复模型"],"ans":1,"explain":"完全恢复模型是以后备副本和事务日志为基础的恢复方法。"},{"id":"dba13170-pl-P4651021","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）恢复模型MySQL支持，确保数据库一致性","opts":["A. 简单恢复","B. 完全恢复","C. 点恢复","D. 日志恢复"],"ans":1,"explain":"MySQL支持完全恢复模型，提供多种技术来确保数据库的一致性。"},{"id":"dba13170-pl-P4651022","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"权限管理的主要目的是（）","opts":["A. 提升系统性能","B. 控制资源访问","C. 增加数据容量","D. 优化用户体验"],"ans":1,"explain":"权限管理的主要目的是对不同的人访问资源的权限进行控制，避免因权限控制缺失或操作不当而引发的风险问题，如操作错误、隐私数据泄露等问题。"},{"id":"dba13170-pl-P4651023","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）通常具有创建表、索引和授予其他用户权限的能力","opts":["A. 普通用户","B. 系统管理员","C. RESOURCE特权用户","D. 备份管理员"],"ans":2,"explain":"这类用户是数据库、表、视图等数据对象的创建者，常称为“具有RESOURCE特权的用户”，拥有这些数据对象上的所有操作和控制的权限，其中主要包括： （1）创建表、索引和聚簇。 （2）可以授予或回收其他用户对其所创建的数据对象的所有访问权限。"},{"id":"dba13170-pl-P4651024","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）用户能连接数据库并查询更新数据","opts":["A. 系统管理员","B. CONNECT特权用户","C. RESOURCE特权用户","D. 备份恢复用户"],"ans":1,"explain":"这类用户可以连接数据库，也称为“具有CONNECT特权的用户”。这类用户的权限主要包括： （1）能够按照所获得的权限查询或更新数据库中的数据。 （2）可以创建视图或定义数据的别名等。"},{"id":"dba13170-pl-P4651025","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"MySQL（）表存储登录账户信息，含49个字段","opts":["A. user表","B. roles表","C. privileges表","D. security表"],"ans":0,"explain":"user表是MySQL安全控制最重要的一个权限表，存储所有登录账户的信息，一共有49个字段，这些字段可以分为4类，分别是范围列、权限列、安全列和资源控制列。"},{"id":"dba13170-pl-P4651026","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）类字段为空时，MySQL会禁止用户访问","opts":["A. 范围列","B. 权限列","C. 安全列","D. 资源控制列"],"ans":2,"explain":"安全列指定用户标识和密码等身份验证信息，如果这些字段为空，则服务器将会向错误日志写入信息，禁止该用户访问。"},{"id":"dba13170-pl-P4651027","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）表存放用户对某个数据库的操作权限","opts":["A. user表","B. roles表","C. db表","D. tables_priv表"],"ans":2,"explain":"db表也是MySQL数据库安全控制重要的权限表，表中存放用户对某个数据库的操作权限。"},{"id":"dba13170-pl-P4651028","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）命令可查看tables_priv表的结构","opts":["A. SHOW TABLES","B. DESC mysql.tables_priv","C. SELECT * FROM mysql.tables_priv","D. EXPLAIN mysql.tables_priv"],"ans":1,"explain":"tables_priv表用于对表设置操作权限，使用DESC语句“DESCmysql.tables_priv;”可查看tables_priv表的结构"},{"id":"dba13170-pl-P4651029","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）表用于对表中某一列设置操作权限","opts":["A. user_priv表","B. db_priv表","C. tables_priv表","D. columns_priv表"],"ans":3,"explain":"columns_priv表用于对表中某一列设置操作权限。"},{"id":"dba13170-pl-P4651030","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）表用于保存存储过程或函数的操作权限","opts":["A. tables_priv表","B. cols_priv表","C. procs_priv表","D. user_priv表"],"ans":2,"explain":"proes_priv表用于保存对某个存储过程或存储函数设置的操作权限。"},{"id":"dba13170-pl-P4651031","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"MySQL权限管理（）分阶段进行认证","opts":["A. 先授权再验证","B. 先连接再分配权限","C. 先认证再授权","D. 先审核再连接"],"ans":2,"explain":"MySQL权限管理系统通过下列两个阶段进行认证。 ①对连接的用户进行身份认证，合法的用户通过认证，不合法的用户拒绝连接。 ②对通过认证的合法用户赋予相应的权限，用户可以在拥有的权限范围内对数据库进行相应的操作。"},{"id":"dba13170-pl-P4651032","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"MySQL8后创建新用户的基本格式是（）","opts":["A. CREATE LOGIN 用户 IDENTIFIED BY 密码","B. CREATE USER 用户名 IDENTIFIED WITH 密码","C. CREATE USER 用户名 IDENTIFIED BY 密码","D. CREATE ACCOUNT 用户名 IDENTIFIED BY 密码"],"ans":2,"explain":"MySQL8之后的版本创建新用户的SQL语句的基本格式：CREATE USER用户名IDENTIFIEDBY密码WIH资制]；"},{"id":"dba13170-pl-P4651033","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）删除MySQL中的普通用户","opts":["A. DROP LOGIN 用户名","B. DELETE FROM mysql.user WHERE 用户名=&#039;xxx&#039;","C. DROP USER &#039;用户名&#039;@&#039;主机名&#039; 或 DELETE FROM mysql.user WHERE 条件","D. REVOKE 用户名"],"ans":2,"explain":"删除普通用户的语句有两种：DROP USER&#039;用户名!，用户名’..];DELETE FROM mysql.user WHERE host=&#039;主机名&#039;AND User =&#039;用户名&#039;；"},{"id":"dba13170-pl-P4651034","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）修改MySQL中root账户的密码","opts":["A. 使用SET PASSWORD命令","B. 利用UPDATE语句直接修改mysql.user表","C. 使用ALTER USER命令","D. 通过user()函数查询当前用户"],"ans":2,"explain":"MySQL有多种修改账户密码的方法，这里列举几种常用的方法。 ①使用ALTERUSER命令修改root账户密码，利用user()函数返回当前连接MySQL的用户名和主机名。"},{"id":"dba13170-pl-P4651035","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"MySQL默认的首个DBA账户是（），且不能删除","opts":["A. admin","B. guest","C. root","D. superuser"],"ans":2,"explain":"MySQL默认生成的第一个DBA账户是root，root具有DBA的全部权限，且不能删除，安装程序不指定root的密码。"},{"id":"dba13170-pl-P4651036","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在MySQL中，（）授予或撤销权限","opts":["A. 使用SET和RESET语句","B. 使用CREATE和DROP语句","C. 使用GRANT和REVOKE语句","D. 使用ADD和REMOVE语句"],"ans":2,"explain":"在MySQL中，使用GRANT和REVOKE语句授予或撤销用户及角色的权限。"},{"id":"dba13170-pl-P4651037","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）操作是GRANT的相反操作，用于收回权限","opts":["A. DELETE","B. DROP","C. REVOKE","D. SUSPEND"],"ans":2,"explain":"REVOKE是GRANT的相反操作，用于收回GRANT授予的权限。"},{"id":"dba13170-pl-P4651038","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）给MySQL角色授权","opts":["A. CREATE ROLE role_name WITH PRIVILEGES","B. GRANT PRIVILEGES ON 表名 TO role_name","C. GRANT 权限 ON 表名 TO &#039;role_name&#039;[@&#039;host_name&#039;]","D. ADD PRIVILEGES TO role_name"],"ans":2,"explain":"创建的新角色是没有任何权限的，需要给角色授权。给角色授权的语法格式：GRANT权限ON表名TO&#039;role_name&#039;[@ &#039;host_name&#039;];"},{"id":"dba13170-pl-P4651039","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"新创建的角色默认权限如何，需（）操作才能赋予其权限","opts":["A. 有全部权限，无需操作","B. 无权限，需手动授权","C. 有只读权限，需提升","D. 有部分权限，需调整"],"ans":1,"explain":"创建的新角色是没有任何权限的，需要给角色授权"},{"id":"dba13170-pl-P4651040","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）查看MySQL角色的权限","opts":["A. SELECT PRIVILEGES FROM role_name","B. SHOW GRANTS OF role_name","C. DESCRIBE ROLE role_name","D. SHOW GRANTS FOR &#039;角色名&#039;"],"ans":3,"explain":"查看角色权限的SQL语句格式：SHOW GRANTS FOR&#039;角色名&#039;；"},{"id":"dba13170-pl-P4651041","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）收回角色teachers在SC表的插入和更新权限","opts":["A. REVOKE INSERT, UPDATE ON SC FROM teachers","B. DROP PRIVILEGES ON SC FOR teachers","C. REVOKE teachers FROM INSERT, UPDATE ON SC","D. REVOKE INSERT, UPDATE ON SC TO teachers"],"ans":0,"explain":"收回角色teachers在SC表的插入和更新权限。"},{"id":"dba13170-pl-P4651042","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"要收回角色teachers在SC表的（）权限","opts":["A. 查询和删除","B. 插入和更新","C. 创建和索引","D. 修改和视图"],"ans":1,"explain":"收回角色teachers在SC表的插入和更新权限。"},{"id":"dba13170-pl-P4651043","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"未激活角色时，将用户赋给某角色，其权限显示为（）","opts":["A. 有效","B. 无效","C. 部分有效","D. NONE"],"ans":3,"explain":"授予角色权限和给用户赋予角色，还需要激活角色才能生效，使用户真正获得角色的权限。在未激活时，如果将用户赋给某个角色，则会显示NONE。"},{"id":"dba13170-pl-P4651044","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"删除角色后，原赋予该角色的用户将会（）","opts":["A. 权限保留","B. 权限提升","C. 权限失效","D. 权限转移"],"ans":2,"explain":"如果删除角色，则赋予角色的用户就无法使用角色的权限。"},{"id":"dba13170-pl-P4651045","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"视图的使用方法在MySQL中类似于（）的操作","opts":["A. 索引","B. 存储过程","C. 表","D. 触发器"],"ans":2,"explain":"视图的使用方法类似于表的操作。"},{"id":"dba13170-pl-P4651046","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"通过视图对数据进行INSERT、UPDATE、DELETE操作，结果会反映到（）","opts":["A. 索引","B. 视图本身","C. 基本表","D. 临时表"],"ans":2,"explain":"视图是从基本表中引用数据，通过视图也可以插入（INSERT）、更新（UPDATE）和删除（DELETE）表中的数据，其操作结果将转换到基本表"},{"id":"dba13170-pl-P4651047","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"以下（）会导致视图不能更新数据","opts":["A. 包含SUM函数","B. 包含主键","C. 包含外键","D. 包含索引"],"ans":0,"explain":"不能更新的情况：视图中包含SUM()、COUNT()、MAX()和MIN()等函数；视图中包含UNION、UNIONALL、DISTINCT、GROUP BY和HAVING等关键字"},{"id":"dba13170-pl-P4651048","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"视图与表的主要区别在于视图是否真实存储（）","opts":["A. 索引信息","B. 数据内容","C. 字段定义","D. 约束条件"],"ans":1,"explain":"视图也可以像表一样查询、插入、删除和修改数据，二者的区别是表的数据真实存储在数据库中，而视图是一个虚表，只有定义，没有存储的数据。"},{"id":"dba13170-pl-P4651049","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在MySQL数据库中，当基本表的某些字段发生变化时，为了保持视图与基本表的一致性，需要执行哪种SQL操作，并且这种操作通常涉及对（）内容的修改","opts":["A. 使用ALTER TABLE语句修改基本表，视图会自动更新","B. 使用UPDATE VIEW语句修改视图，以反映基本表的变化","C. 使用CREATE OR REPLACE VIEW语句重新创建视图，确保与基本表一致","D. 使用ALTER VIEW语句修改视图定义，以匹配基本表的新结构"],"ans":3,"explain":"由于题目要求根据提供的材料选择最符合题意的答案，且材料中提到“修改视图的SQL语句格式”，在假设存在一个类似ALTER VIEW的通用概念（尽管MySQL不直接支持）下，D选项是最接近题意的。"},{"id":"dba13170-pl-P4651159","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_______________是一种人为破坏计算机正常工作的特殊程序。","opts":[],"ans":null,"explain":"计算机病毒"},{"id":"dba13170-pl-P4651160","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"数据库系统中故障对数据库的破坏可划分为哪两类？","opts":[],"ans":null,"explain":"一类是数据库本身被破坏，如介质故障或病毒破坏；另一类是数据库正确性被破坏，如事务、系统故障或某些病毒导致的未完成事务修改。"},{"id":"dba13170-pl-P4651161","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_________是指将数据库转储到磁带或另一个磁盘上保存的过程。","opts":[],"ans":null,"explain":"备份（Backup）"},{"id":"dba13170-pl-P4651162","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:____________是指对操作系统下数据库物理文件（如数据文件、日志文件等）的备份。","opts":[],"ans":null,"explain":"物理备份"},{"id":"dba13170-pl-P4651163","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:__________是指对数据库逻辑组件（如表等数据库对象）的备份。","opts":[],"ans":null,"explain":"逻辑备份"},{"id":"dba13170-pl-P4651164","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_____________：备份整个数据库，包含用户表、系统表、索引、视图和存储过程等所有数据库对象。","opts":[],"ans":null,"explain":"完全备份"},{"id":"dba13170-pl-P4651165","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:___________：只备份上次完全备份或者增量备份之后被修改的内容。","opts":[],"ans":null,"explain":"增量备份"},{"id":"dba13170-pl-P4651166","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:______________命令的基本语法格式：mysqldump -u root -p[密码][数据库名]&gt;\\目录\\备份文件名.sql","opts":[],"ans":null,"explain":"mysql dump"},{"id":"dba13170-pl-P4651167","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:事务日志记录对数据库的所有更新操作，也称为__________。","opts":[],"ans":null,"explain":"运行记录"},{"id":"dba13170-pl-P4651168","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述事务日志一般包括哪些方面内容","opts":[],"ans":null,"explain":"1、事务的开始标记（STARTTRANSACTION）。<br/>2、事务的结束状态（COMMIT或ROLLBACK）。<br/>3、事务的更新操作：更新的数据对象、更新前的值（前像）、更新后的值（后像）。"},{"id":"dba13170-pl-P4651169","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:事务日志中保存__________恢复所必需的数据。","opts":[],"ans":null,"explain":"数据库"},{"id":"dba13170-pl-P4651170","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_____________是MySQL数据库的重要组成部分和特色。","opts":[],"ans":null,"explain":"日志文件"},{"id":"dba13170-pl-P4651171","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:将数据库从某种故障状态恢复到正确状态的处理过程称为______________","opts":[],"ans":null,"explain":"数据库恢复。"},{"id":"dba13170-pl-P4651172","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:____________是以后备副本为基础的恢复方法。","opts":[],"ans":null,"explain":"简单恢复模型"},{"id":"dba13170-pl-P4651173","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_____________是对用户访问数据库各种资源（如表、视图、系统目录、实用程序等）的权限（包括创建、查询、修改、删除、执行等）的控制。","opts":[],"ans":null,"explain":"访问控制"},{"id":"dba13170-pl-P4651174","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述DBA拥有支配整个数据库资源的所有特权，其中主要包括什么？","opts":[],"ans":null,"explain":"（1）访问数据库的任何数据。<br/>（2）数据库的调整、重构和重组。<br/>（3）注册用户，授予和回收数据库用户访问数据对象的权限。<br/>（4）控制整个数据库的运行和跟踪审查。<br/>（5）数据库备份和恢复等。"},{"id":"dba13170-pl-P4651175","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:删除普通用户的语句有两种：____________用户名!，用户名’..];","opts":[],"ans":null,"explain":"DROP USER&#039;"},{"id":"dba13170-pl-P4651176","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:_________默认生成的第一个DBA账户是root，root具有DBA的全部权限，且不能删除，安装程序不指定root的密码。","opts":[],"ans":null,"explain":"MySQL"},{"id":"dba13170-pl-P4651177","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:在MySQL中，使用_________和REVOKE语句授予或撤销用户及角色的权限。","opts":[],"ans":null,"explain":"GRANT"},{"id":"dba13170-pl-P4651178","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:________是GRANT的相反操作，用于收回GRANT授予的权限。","opts":[],"ans":null,"explain":"REVOKE"},{"id":"dba13170-pl-P4651179","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:SQL语句格式：___________________","opts":[],"ans":null,"explain":"CREATE ROLE role_name;"},{"id":"dba13170-pl-P4651180","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:在SQL中，要查看角色的权限，应使用以下____________命令","opts":[],"ans":null,"explain":"SHOW ROLE GRANTS"},{"id":"dba13170-pl-P4651181","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请简述给用户赋予角色的SQL语法格式，并指出在执行此操作时需要注意的关键点。","opts":[],"ans":null,"explain":"给用户赋予角色的SQL语法格式为：GRANT ROLE [角色名] TO [用户名];。在执行此操作时，需确保角色名和用户名均存在且正确无误，以避免语法错误或权限问题。"},{"id":"dba13170-pl-P4651182","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:撤销用户所担任角色的SQL语法格式为：REVOKE ROLE [角色名] FROM [______];","opts":[],"ans":null,"explain":"REVOKE ROLE [角色名] FROM [用户名]"},{"id":"dba13170-pl-P4651183","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请详细描述激活角色的两种方式，并解释在何种情况下这两种方式可能会被使用，以及它们如何影响用户的权限。","opts":[],"ans":null,"explain":"激活角色有两种方式：一是使用SETDEFAULTROLE命令指定默认角色；二是将activate_all_roles_on_login变量设为ON，使登录时自动激活所有角色。这两种方式决定了用户会话中的可用权限。"},{"id":"dba13170-pl-P4651184","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请简述在SQL中删除一个已存在角色的基本语法，并指出需要替换的部分是什么。","opts":[],"ans":null,"explain":"使用DROP ROLE role_name;语法删除角色，其中role_name需替换为要删除的角色名。"},{"id":"dba13170-pl-P4651185","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请简述如何基于客户表创建一个名为通讯录的视图，且该视图仅允许查看客户名称、联系人姓名和电话号码这三个字段的信息？","opts":[],"ans":null,"explain":"可以使用CREATE VIEW语句，指定视图名称为通讯录，通过SELECT子句选择客户名称、联系人姓名和电话号码这三个字段，从客户表中创建视图。"},{"id":"dba13170-pl-P4651186","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:创建销售视图需连接____、订单、订单明细和商品四个表，以获取完整销售信息。","opts":[],"ans":null,"explain":"客户"},{"id":"dba13170-pl-P4651187","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"在MySQL数据库中，假设有一个名为“客户表”的表，其中包含一个名为“电话号码”的字段。现在，为了更符合业务需求，需要将该字段名改为“手机号”。同时，数据库中还存在一个依赖于“客户表”的视图，名为“通讯录视图”。请描述以下操作过程及其可能的影响： 1.在MySQL命令行窗口中，输入哪条SQL语句可以将“客户表”中的“电话号码”字段名改为“手机号”？ 2.修改字段名后，直接查询“通讯录视图”会出现什么情况？为什么？ 3.为了保持“通讯录视图”的有效性，你需要采取什么措施？请简述步骤。","opts":[],"ans":null,"explain":"1.在MySQL命令行窗口中，可以使用ALTER TABLE语句来修改字段名。具体的SQL语句如下：ALTER TABLE 客户表 CHANGE 电话号码 手机号 数据类型;其中，“数据类型”应替换为原“电话号码”字段的数据类型（如VARCHAR(20)）。注意，CHANGE关键字用于同时修改字段名和（可选地）数据类型。如果只想修改字段名而保持数据类型不变，可以省略数据类型部分，但通常建议明确指定以避免潜在问题。<br/><br/>2.修改字段名后，直接查询“通讯录视图”会出现错误。因为视图是基于表的定义创建的，当表的字段名发生变化时，视图中的相应引用也会变得无效。这会导致查询视图时MySQL无法找到正确的字段，从而抛出错误。<br/><br/>3.为了保持“通讯录视图”的有效性，需要采取以下措施：<br/>A.首先，使用DROP VIEW语句删除原有的“通讯录视图”。DROP VIEW 通讯录视图;<br/>B.然后，根据修改后的“客户表”结构，使用CREATE VIEW语句重新创建“通讯录视图”。CREATE VIEW 通讯录视图 AS  <br/>SELECT 手机号, 其他字段...  <br/>FROM 客户表  <br/>WHERE 条件...;<br/>在上面的SQL语句中，“其他字段...”和“条件...”应替换为视图实际需要的字段和筛选条件。<br/><br/>通过这两个步骤，可以确保“通讯录视图”在“客户表”字段名修改后仍然能够正确反映数据。"},{"id":"dba13170-pl-P4651188","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"在MySQL中，如果用户希望删除一个或多个视图，并且确保自己具备相应的权限，应使用什么语句以及需要哪些权限？请简要描述删除视图的语法格式。","opts":[],"ans":null,"explain":"在MySQL中，如果用户希望删除一个或多个视图，应使用DROP VIEW语句。执行此操作的用户必须拥有对相应视图的DROP权限。<br/><br/>删除视图的语法格式如下：DROP VIEW 视图名1[,视图名2,...];"},{"id":"dba13170-pl-P4651189","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"填空题:在MySQL数据库中，当用户需要删除一个或多个视图时，应使用以下____________（SQL）语句，并且需要____________条件","opts":[],"ans":null,"explain":"使用DROP VIEW语句，并需要拥有DROP权限"}];
